insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('sozialhuefe', 'Sozialhüfe', '', '', '', '', 'Sozialhilfe', '[{"kategorie": "jur.", "text": "\"staatliche Unterstützungsleistung, die Personen in sozialen Notlagen helfen soll, ihren Lebensunterhalt zu sichern\" (bis 2020 \"Mindestsicherung\" genannt);  2.Sie richtet sich an Menschen, die kein oder nur ein sehr geringes Einkommen haben und keine anderen Ansprüche auf staatliche Leistungen wie Arbeitslosengeld oder [[Notstandshilfe]] mehr besitzen"}, {"kategorie": "", "text": "Die Mindestsicherung dient der Existenzsicherung und soll das soziokulturelle Minimum abdecken, das zum Leben in der Gesellschaft notwendig ist"}, {"kategorie": "", "text": "Die Mindestsicherung soll finanzielle Unterstützung bieten, um die Grundbedürfnisse des täglichen Lebens wie Wohnung, Essen, Kleidung und Gesundheitsversorgung zu decken, wenn keine anderen finanziellen Mittel zur Verfügung stehen"}, {"kategorie": "", "text": "Anspruch auf Mindestsicherung haben Personen, die in sozialer Not sind, also kein oder nur ein sehr geringes Einkommen haben, sowie keine anderen Ansprüche auf [[Arbeitslosengeld]], Notstandshilfe oder Pension. Auch Menschen, die nur ein geringes Einkommen haben, das nicht zur Deckung des Lebensunterhalts ausreicht, können die Leistung erhalten"}, {"kategorie": "", "text": "Die Höhe der Mindestsicherung orientiert sich an einem bundeseinheitlichen Richtwert, der die Mindestkosten für ein würdiges Leben abdecken soll. Diese Unterstützung ist abhängig von der individuellen Lebenssituation und den Bedürfnissen der Antragsteller, wie etwa der Anzahl der Haushaltsmitglieder"}, {"kategorie": "", "text": "Für alleinstehende Erwachsene liegt der Richtsatz bei etwa 885 Euro monatlich (Stand 2024), während Haushalte mit mehreren Personen höhere Beträge erhalten"}, {"kategorie": "", "text": "Neben dem Grundbetrag für den Lebensunterhalt kann die Mindestsicherung auch Zuschüsse für Wohnkosten, Krankenversicherung und in besonderen Fällen zusätzliche Leistungen für Bildung oder Pflegebedarf umfassen."}]'::jsonb, ''),
  ('mindestsicharung', 'Mindestsicharung', '', '', '', '', 'Mindestsicherung', '[{"kategorie": "jur.", "text": "\"staatliche Unterstützungsleistung, die Personen in sozialen Notlagen helfen soll, ihren Lebensunterhalt zu sichern\" (seit 2020 \"Sozialhilfe\" genannt);  2.Sie richtet sich an Menschen, die kein oder nur ein sehr geringes Einkommen haben und keine anderen Ansprüche auf staatliche Leistungen wie Arbeitslosengeld oder [[Notstandshilfe]] mehr besitzen"}, {"kategorie": "", "text": "Die Mindestsicherung dient der Existenzsicherung und soll das soziokulturelle Minimum abdecken, das zum Leben in der Gesellschaft notwendig ist"}, {"kategorie": "", "text": "Die Mindestsicherung soll finanzielle Unterstützung bieten, um die Grundbedürfnisse des täglichen Lebens wie Wohnung, Essen, Kleidung und Gesundheitsversorgung zu decken, wenn keine anderen finanziellen Mittel zur Verfügung stehen"}, {"kategorie": "", "text": "Anspruch auf Mindestsicherung haben Personen, die in sozialer Not sind, also kein oder nur ein sehr geringes Einkommen haben, sowie keine anderen Ansprüche auf [[Arbeitslosengeld]], Notstandshilfe oder Pension. Auch Menschen, die nur ein geringes Einkommen haben, das nicht zur Deckung des Lebensunterhalts ausreicht, können die Leistung erhalten"}, {"kategorie": "", "text": "Die Höhe der Mindestsicherung orientiert sich an einem bundeseinheitlichen Richtwert, der die Mindestkosten für ein würdiges Leben abdecken soll. Diese Unterstützung ist abhängig von der individuellen Lebenssituation und den Bedürfnissen der Antragsteller, wie etwa der Anzahl der Haushaltsmitglieder"}, {"kategorie": "", "text": "Für alleinstehende Erwachsene liegt der Richtsatz bei etwa 885 Euro monatlich (Stand 2024), während Haushalte mit mehreren Personen höhere Beträge erhalten"}, {"kategorie": "", "text": "Neben dem Grundbetrag für den Lebensunterhalt kann die Mindestsicherung auch Zuschüsse für Wohnkosten, Krankenversicherung und in besonderen Fällen zusätzliche Leistungen für Bildung oder Pflegebedarf umfassen."}]'::jsonb, ''),
  ('notschdaundshueuefe', 'Notschdaundshüüfe', '', '', '', '', 'Notstandshilfe', '[{"kategorie": "jur.", "text": "\"finanzielle Leistung in Österreich, die an Arbeitslose gezahlt wird, die ihren Anspruch auf [[Arbeitslosengeld]] ausgeschöpft haben und weiterhin keine Beschäftigung finden\""}, {"kategorie": "", "text": "Sie dient der Existenzsicherung von arbeitslosen Personen, die nach der Bezugsdauer des Arbeitslosengeldes noch arbeitslos sind und ihren Lebensunterhalt nicht selbstständig sichern können"}, {"kategorie": "", "text": "Die Notstandshilfe kann erst dann beantragt werden, wenn der Anspruch auf Arbeitslosengeld erschöpft ist. Der Antragsteller muss weiterhin arbeitsfähig und arbeitswillig sein und darf keine Beschäftigung gefunden haben"}, {"kategorie": "", "text": "Die Höhe der Notstandshilfe richtet sich nach der vorherigen Höhe des Arbeitslosengeldes und den persönlichen Verhältnissen des Antragstellers. Sie beträgt in der Regel 92–95 % des zuletzt bezogenen Arbeitslosengeldes. Es gibt kein festgelegtes Maximum, jedoch werden finanzielle Rücklagen oder das Einkommen des Partners bei der Berechnung berücksichtigt"}, {"kategorie": "", "text": "Für die Notstandshilfe wird eine Bedarfsprüfung durchgeführt, bei der geprüft wird, ob der Antragsteller und dessen Haushalt genügend finanzielle Mittel haben, um den Lebensunterhalt selbst zu bestreiten. Dabei kann auch das Einkommen des Ehepartners oder Lebensgefährten in die Berechnung einbezogen werden"}, {"kategorie": "", "text": "Die Notstandshilfe wird für einen befristeten Zeitraum gewährt, kann aber immer wieder neu beantragt werden, solange die Voraussetzungen erfüllt sind. Es gibt keine feste zeitliche Begrenzung für den Bezug von Notstandshilfe, sofern der Arbeitslose weiterhin alle Voraussetzungen erfüllt"}, {"kategorie": "", "text": "Die Notstandshilfe unterscheidet sich von der [[Mindestsicherung]] (Sozialhilfe). Während die Notstandshilfe für Personen gedacht ist, die zuvor Arbeitslosengeld bezogen haben, richtet sich die Mindestsicherung an Personen, die überhaupt keine anderen finanziellen Mittel zur Verfügung haben."}]'::jsonb, ''),
  ('taeaeta', 'Tääta', '', '', '', '', 'Täter', '[{"kategorie": "", "text": "Diese Person wird nach einem gerichtlichen Verfahren durch ein rechtskräftiges [[Urteil]] für schuldig befunden und trägt somit die rechtlichen Konsequenzen ihrer Tat"}, {"kategorie": "", "text": "Ein Straftäter begeht eine Handlung, die den [[Tatbestand]] einer [[Straftat]] erfüllt. Straftaten können unterschiedlich schwerwiegend sein, von geringfügigen Vergehen wie Diebstahl bis hin zu schweren Verbrechen wie Mord oder Raub"}, {"kategorie": "", "text": "Um als Straftäter zu gelten, muss die Schuld der Person durch ein [[Gericht]] im Rahmen eines [[Strafverfahrens]] nachgewiesen werden. Bis zur rechtskräftigen Verurteilung gilt die Person als unschuldig, gemäß dem Prinzip der [[Unschuldsvermutung]]"}, {"kategorie": "", "text": "Nach der Verurteilung wird der Straftäter mit einer [[Strafe]] belegt, die je nach Schwere der Tat unterschiedlich ausfallen kann. Strafen reichen von [[Geldstrafen]] und [[Bewährungsstrafen]] bis zu [[Freiheitsstrafen]] (Gefängnis)"}, {"kategorie": "", "text": "Straftäter können ihre Tat entweder vorsätzlich (bewusst und gewollt) oder fahrlässig (durch Sorgfaltsmangel) begehen. Vorsätzliche Straftaten werden in der Regel schwerer bestraft als fahrlässige Handlungen."}]'::jsonb, ''),
  ('schdroftaeaeta', 'Schdroftääta', '', '', '', '', 'Straftäter', '[{"kategorie": "jur.", "text": "\"Person, die eine rechtswidrige Handlung begangen hat, die nach dem [[Strafgesetz]] mit einer [[Strafe]] bedroht ist\""}, {"kategorie": "", "text": "Diese Person wird nach einem gerichtlichen Verfahren durch ein rechtskräftiges [[Urteil]] für schuldig befunden und trägt somit die rechtlichen Konsequenzen ihrer Tat"}, {"kategorie": "", "text": "Ein Straftäter begeht eine Handlung, die den [[Tatbestand]] einer [[Straftat]] erfüllt. Straftaten können unterschiedlich schwerwiegend sein, von geringfügigen Vergehen wie Diebstahl bis hin zu schweren Verbrechen wie Mord oder Raub"}, {"kategorie": "", "text": "Um als Straftäter zu gelten, muss die Schuld der Person durch ein [[Gericht]] im Rahmen eines [[Strafverfahrens]] nachgewiesen werden. Bis zur rechtskräftigen Verurteilung gilt die Person als unschuldig, gemäß dem Prinzip der [[Unschuldsvermutung]]"}, {"kategorie": "", "text": "Nach der Verurteilung wird der Straftäter mit einer [[Strafe]] belegt, die je nach Schwere der Tat unterschiedlich ausfallen kann. Strafen reichen von [[Geldstrafen]] und [[Bewährungsstrafen]] bis zu [[Freiheitsstrafen]] (Gefängnis)"}, {"kategorie": "", "text": "Straftäter können ihre Tat entweder vorsätzlich (bewusst und gewollt) oder fahrlässig (durch Sorgfaltsmangel) begehen. Vorsätzliche Straftaten werden in der Regel schwerer bestraft als fahrlässige Handlungen."}]'::jsonb, ''),
  ('schrofvafoigungsbehoeade', 'Schrofvafoigungsbehöade', '', '', '', '', 'Strafverfolgungsbehörde', '[{"kategorie": "jur.", "text": "\"staatliche Institution, die für die Ermittlung, Verfolgung und Ahndung von Straftaten zuständig ist\""}, {"kategorie": "", "text": "Diese Behörden arbeiten zusammen, um Straftaten aufzuklären, die Täter zu identifizieren und zur Rechenschaft zu ziehen sowie die öffentliche Sicherheit zu gewährleisten"}, {"kategorie": "", "text": "Zu den Strafverfolgungsbehörden gehören insbesondere [[Polizei]], [[Staatsanwaltschaft]], [[Gerichte]] und [[Finanzbehörden]] (zuständig für die Verfolgung von Steuerdelikten)"}, {"kategorie": "", "text": "Strafverfolgungsbehörden sind für die Aufklärung von Straftaten verantwortlich. Die Polizei führt in der Regel die Ermittlungen durch, sammelt Beweise, befragt Zeugen und Verdächtige und erstellt Berichte, die an die Staatsanwaltschaft weitergeleitet werden"}, {"kategorie": "", "text": "Die Staatsanwaltschaft leitet und überwacht die strafrechtlichen Ermittlungen. Sie entscheidet, ob [[Anklage]] erhoben wird, und vertritt den [[Staat]] in [[Strafprozessen]] vor Gericht"}, {"kategorie": "", "text": "Die Strafverfolgungsbehörden sorgen dafür, dass [[Straftäter]] für ihre Handlungen zur Rechenschaft gezogen werden. Dies geschieht durch Anklageerhebung, Gerichtsverhandlungen und die Verhängung von [[Strafen]], falls der Täter für schuldig befunden wird"}, {"kategorie": "", "text": "Die Strafverfolgungsbehörden handeln auf Grundlage der [[Gesetze]] und sind an die Grundsätze des [[Rechtsstaats]] gebunden. Dies bedeutet, dass die Rechte der Verdächtigen respektiert werden müssen, darunter das Recht auf [[Unschuldsvermutung]], faire Verfahren und [[rechtliches]] Gehör."}]'::jsonb, ''),
  ('gewoitvabrechn', 'Gewoitvabrechn', '', '', '', '', 'Gewaltverbrechen', '[{"kategorie": "jur.", "text": "\"Straftat, bei der der Täter körperliche Gewalt anwendet oder androht, um sein Ziel zu erreichen\""}, {"kategorie": "", "text": "Diese Verbrechen richten sich häufig gegen die körperliche Unversehrtheit oder das Leben einer Person und beinhalten ernste Verletzungen, Bedrohungen oder den Tod des Opfers. Gewaltverbrechen gehören zu den schwersten Straftaten und werden entsprechend hart bestraft"}, {"kategorie": "", "text": "Beispiele für Gewaltverbrechen:  (i) Mord oder Totschlag (die absichtliche oder fahrlässige Tötung eines Menschen),  (ii) Raub (die gewaltsame Entwendung von Eigentum unter Anwendung oder Androhung von Gewalt),  (iii) Körperverletzung (Zufügung von physischen Schäden an einer Person),  (iv) Vergewaltigung (die erzwungene sexuelle Handlung durch Gewalt oder Drohung),  (v) Schwere Nötigung: Das Erzwingen einer Handlung durch Gewaltandrohung"}, {"kategorie": "", "text": "Aufgrund ihrer Schwere unterliegen Gewaltverbrechen in der Regel strengen Strafen, die von langjährigen Freiheitsstrafen bis hin zu lebenslanger Haft reichen, je nach Art und Schwere des Vergehens"}, {"kategorie": "", "text": "Die Bekämpfung von Gewaltverbrechen ist eine der obersten Prioritäten der [[Strafverfolgungsbehörden]], da diese Verbrechen eine ernste Gefahr für die öffentliche Sicherheit und das Leben von Menschen darstellen."}]'::jsonb, ''),
  ('sozialvasicharung', 'Sozialvasicharung', '', '', '', '', 'Sozialversicherung', '[{"kategorie": "jur.", "text": "\"gesetzlich geregeltes System der sozialen Absicherung, das Arbeitnehmer, Selbstständige und andere Bevölkerungsgruppen gegen soziale Risiken wie Krankheit, Arbeitsunfähigkeit, Arbeitslosigkeit, Pflegebedürftigkeit und Alter finanziell absichert\""}, {"kategorie": "", "text": "Die Sozialversicherung wird durch Beiträge von Arbeitnehmern und Arbeitgebern finanziert und bietet eine Vielzahl von Leistungen im Bereich der Kranken-, Unfall-, Arbeitslosen- und Pensionsversicherung"}, {"kategorie": "", "text": "In Österreich besteht eine Pflichtversicherung für Arbeitnehmer, Selbstständige und bestimmte andere Personengruppen. Das bedeutet, dass alle Arbeitnehmer sowie selbstständig Erwerbstätige und bestimmte andere Gruppen automatisch in das Sozialversicherungssystem einbezogen werden und Beiträge leisten müssen"}, {"kategorie": "", "text": "Die Sozialversicherung in Österreich gliedert sich in drei Hauptbereiche:  (i) Krankenversicherung (sie deckt Kosten für medizinische Behandlungen, Spitalsaufenthalte, Medikamente und Vorsorgeuntersuchungen ab),  (ii) Pensionsversicherung (sie sichert die finanzielle Versorgung im Alter, bei Invalidität oder für Hinterbliebene im Todesfall des Versicherten),  (iii) Unfallversicherung (diese Versicherung bietet Schutz bei Arbeitsunfällen und Berufskrankheiten und deckt medizinische Behandlungen, Rehabilitation und Invaliditätsrenten)"}, {"kategorie": "", "text": "Ein weiteres wesentliches Element der Sozialversicherung ist die Arbeitslosenversicherung, die durch Beiträge der Arbeitnehmer und Arbeitgeber finanziert wird. Sie gewährt Leistungen wie Arbeitslosengeld, [[Notstandshilfe]] und hilft bei der Wiedereingliederung in den Arbeitsmarkt"}, {"kategorie": "", "text": "Die Verwaltung der Sozialversicherung erfolgt durch verschiedene Sozialversicherungsträger, die jeweils für spezifische Bereiche zuständig sind:  (i) Die Österreichische Gesundheitskasse (ÖGK) für die Krankenversicherung,  (ii) Die Pensionsversicherungsanstalt (PVA) für die Alters- und Invaliditätsversorgung,  (iii) Die Allgemeine Unfallversicherungsanstalt (AUVA) für die Unfallversicherung"}, {"kategorie": "", "text": "Die österreichische Sozialversicherung funktioniert nach dem Solidaritätsprinzip: Die Beiträge richten sich nach dem Einkommen, die Leistungen hingegen nach dem Bedarf. So tragen Besserverdienende zur Finanzierung der Leistungen für Geringverdiener oder Bedürftige bei"}, {"kategorie": "", "text": "Das Sozialversicherungssystem ist eine zentrale Säule der sozialen Sicherheit in Österreich. Es soll sicherstellen, dass alle Bürger in kritischen Lebenssituationen wie Krankheit, Alter, Arbeitslosigkeit oder Unfall finanziell abgesichert sind."}]'::jsonb, ''),
  ('sozialvasicharungsbeitrog', 'Sozialvasicharungsbeitrog', '', '', '', '', 'Sozialversicherungsbeitrag', '[{"kategorie": "jur.", "text": "\"gesetzlich vorgeschriebene Abgabe, die von Arbeitnehmern und Arbeitgebern an die [[Sozialversicherung]] gezahlt wird, um die finanzielle Grundlage für die soziale Absicherung der Versicherten zu gewährleisten\""}, {"kategorie": "", "text": "Diese Beiträge werden vom Einkommen der Arbeitnehmer abgezogen und dienen dazu, die Leistungen der Kranken-, Renten-, Pflege- und Arbeitslosenversicherung zu finanzieren"}, {"kategorie": "", "text": "Sozialversicherungsbeiträge sind in den meisten Ländern, darunter auch in Österreich und Deutschland, für Arbeitnehmer obligatorisch. Die Beitragspflicht ist gesetzlich geregelt, und sowohl Arbeitnehmer als auch Arbeitgeber sind verpflichtet, einen Anteil zu leisten"}, {"kategorie": "", "text": "Der Beitrag wird in der Regel zwischen Arbeitnehmer und Arbeitgeber aufgeteilt. Der Arbeitgeber führt den gesamten Betrag an die zuständige Sozialversicherung ab, zieht jedoch den Arbeitnehmeranteil direkt vom Bruttolohn ab"}, {"kategorie": "", "text": "Der Sozialversicherungsbeitrag wird als Prozentsatz des Bruttoeinkommens berechnet. Die Höhe des Prozentsatzes variiert je nach Art der Versicherung (z. B. Krankenversicherung, Rentenversicherung) und dem jeweiligen Einkommensniveau. Es gibt jedoch Beitragsbemessungsgrenzen, ab denen keine weiteren Beiträge erhoben werden"}, {"kategorie": "", "text": "Sozialversicherungsbeiträge finanzieren die sozialen Sicherungssysteme eines Landes und sorgen dafür, dass Arbeitnehmer im Falle von Krankheit, Arbeitslosigkeit, Unfall oder im Alter abgesichert sind: (i) \nKrankenversicherung (deckt Kosten für medizinische Behandlungen und Krankenhausaufenthalte),  (ii) Rentenversicherung (sichert die finanzielle Versorgung im Alter),  (iii) Arbeitslosenversicherung (unterstützt Arbeitnehmer im Fall von Arbeitslosigkeit),  (iv) Pflegeversicherung (deckt Pflegeleistungen im Alter oder bei Pflegebedürftigkeit)."}]'::jsonb, ''),
  ('tarifvatrog', 'Tarifvatrog', '', '', '', '', 'Tarifvertrag', '[{"kategorie": "jur.", "text": "\"schriftliche Vereinbarung zwischen Arbeitgebern oder Arbeitgeberverbänden und [[Gewerkschaften]], die Arbeitsbedingungen und Entlohnung für eine bestimmte Gruppe von Arbeitnehmern festlegt\""}, {"kategorie": "", "text": "Der Tarifvertrag regelt die Löhne, Arbeitszeiten, Urlaubsansprüche sowie weitere Arbeitsbedingungen und gilt für alle Arbeitnehmer, die dem Geltungsbereich des Tarifvertrags unterliegen, in der Regel innerhalb einer bestimmten Branche oder eines Berufsbereichs"}, {"kategorie": "", "text": "Ein Tarifvertrag wird zwischen den [[Gewerkschaften]] als Vertretung der Arbeitnehmer und den Arbeitgebern oder deren Verbänden ausgehandelt. Er gilt für alle Mitglieder der verhandelnden Parteien und deckt einen festgelegten Bereich, z. B. eine Branche oder ein Unternehmen, ab"}, {"kategorie": "", "text": "Der Tarifvertrag legt die wesentlichen Arbeitsbedingungen fest, darunter: (i) Löhne und Gehälter (Tarifentgelte), (ii) Arbeitszeiten,\nUrlaubsansprüche, (iii) Zulagen (z. B. Schichtzulagen, Weihnachtsgeld), (iv) Kündigungsfristen und andere Regelungen zur Sicherheit und Arbeitsbedingungen"}, {"kategorie": "", "text": "Ein Tarifvertrag gilt für alle Arbeitnehmer und Arbeitgeber, die tarifgebunden sind. Das bedeutet, dass Arbeitgeber, die dem jeweiligen Arbeitgeberverband angehören, und Arbeitnehmer, die Mitglieder der verhandelnden Gewerkschaft sind, an den Tarifvertrag gebunden sind"}, {"kategorie": "", "text": "Die Tarifverhandlungen zwischen Gewerkschaften und Arbeitgebern finden in der Regel in regelmäßigen Abständen statt, um die Arbeitsbedingungen neu zu verhandeln oder anzupassen. Bei Unstimmigkeiten kann es zu Streiks oder anderen Arbeitskämpfen kommen, um die Durchsetzung der Forderungen zu unterstützen"}, {"kategorie": "", "text": "Tarifverträge haben in der Regel eine befristete Laufzeit (z. B. zwei Jahre) und müssen nach Ablauf der Frist neu verhandelt oder verlängert werden. Während der Laufzeit des Tarifvertrags besteht in der Regel Friedenspflicht, das heißt, es darf nicht gestreikt werden"}, {"kategorie": "", "text": "Tarifverträge sind rechtsverbindlich und gelten wie gesetzliche Vorgaben. Sie dürfen nicht zu Ungunsten der Arbeitnehmer durch individuelle Arbeitsverträge umgangen werden."}]'::jsonb, ''),
  ('aungeschdoeoeta', 'Aungeschdööta', '', '', '', '', 'Angestellter', '[{"kategorie": "jur.", "text": "\"Person, die in einem Arbeitsverhältnis steht und im Rahmen einer vertraglichen Vereinbarung überwiegend geistige, kaufmännische oder administrative Tätigkeiten ausführt\""}, {"kategorie": "", "text": "Im Gegensatz zu [[Arbeitern]], deren Aufgaben oft körperlicher oder handwerklicher Natur sind, konzentrieren sich Angestellte auf Büroarbeiten, Verwaltungsaufgaben oder Dienstleistungen"}, {"kategorie": "", "text": "Ein Angestellter arbeitet im Rahmen eines Arbeitsvertrags für einen Arbeitgeber, der seine Pflichten und Rechte sowie die Arbeitsbedingungen festlegt. Dazu gehören Regelungen zu Lohn, Arbeitszeit, Urlaub und Kündigungsfristen"}, {"kategorie": "", "text": "Angestellte werden in der Regel auf Monatsbasis entlohnt, wobei das Gehalt für die erbrachten Arbeitsleistungen vereinbart wird. Es kann sich auch um fixe Gehälter oder variable Anteile handeln, wie z. B. Provisionen oder Bonuszahlungen"}, {"kategorie": "", "text": "Angestellte unterliegen speziellen arbeitsrechtlichen Regelungen, die teilweise von denen der [[Arbeiter]] abweichen. Zum Beispiel können Kündigungsfristen, Urlaubsansprüche und Krankheitsregelungen unterschiedlich sein. Diese Unterschiede sind oft in [[Tarifverträgen]] oder individuellen Arbeitsverträgen festgelegt"}, {"kategorie": "", "text": "Wie alle Arbeitnehmer sind auch Angestellte in das Sozialsystem eingebunden und zahlen Beiträge zur Kranken-, Renten- und Arbeitslosenversicherung. Diese Beiträge werden automatisch vom Gehalt abgezogen"}, {"kategorie": "", "text": "Angestellte haben in vielen Ländern das Recht auf betriebliche Mitbestimmung. Sie können z. B. in [[Betriebsräten]] vertreten sein und so bei Entscheidungen des Unternehmens, die die Arbeitnehmer betreffen, Einfluss nehmen."}]'::jsonb, ''),
  ('geweakschoft', 'Geweakschoft', '', '', '', '', 'Gewerkschaft', '[{"kategorie": "jur.", "text": "\"Organisation von Arbeitnehmern, die gegründet wurde, um deren gemeinsame Interessen gegenüber Arbeitgebern und in der Politik zu vertreten\""}, {"kategorie": "", "text": "Gewerkschaften setzen sich für bessere Arbeitsbedingungen, höhere Löhne, Sicherheit am Arbeitsplatz und den Schutz von Arbeitnehmerrechten ein"}, {"kategorie": "", "text": "Sie sind in der Regel nach Branchen oder Berufsgruppen organisiert und verhandeln häufig Tarifverträge mit Arbeitgebern"}, {"kategorie": "", "text": "Gewerkschaften vertreten die kollektiven Interessen der Arbeitnehmer in Verhandlungen mit Arbeitgebern oder Arbeitgeberverbänden. Dazu gehören Forderungen nach besseren Löhnen, gerechteren Arbeitszeiten, Urlaubsregelungen sowie Maßnahmen zur Sicherheit und Gesundheit am Arbeitsplatz"}, {"kategorie": "", "text": "Eine der Hauptaufgaben von Gewerkschaften ist die Aushandlung von Tarifverträgen, die für bestimmte Branchen oder Berufsgruppen gelten. Tarifverträge regeln u. a. Löhne, Arbeitsbedingungen und Sozialleistungen und bieten den Arbeitnehmern einen rechtlichen Rahmen, der über den gesetzlichen Mindeststandards liegt"}, {"kategorie": "", "text": "Gewerkschaften haben das Recht zum Streik, wenn es zu Konflikten zwischen Arbeitgebern und Arbeitnehmern kommt, etwa bei Tarifverhandlungen. Streiks sind ein wichtiges Druckmittel, um die Forderungen der Gewerkschaft durchzusetzen, wenn Verhandlungen scheitern"}, {"kategorie": "", "text": "Gewerkschaften bieten ihren Mitgliedern rechtliche Beratung und Unterstützung bei arbeitsrechtlichen Problemen, wie Kündigungen oder Arbeitskonflikten. In vielen Fällen übernehmen Gewerkschaften die Rechtsvertretung für ihre Mitglieder vor Arbeitsgerichten"}, {"kategorie": "", "text": "Gewerkschaften spielen eine wichtige Rolle in der Politik und setzen sich für soziale Gerechtigkeit und Arbeitnehmerrechte ein. Sie üben Einfluss auf politische Entscheidungen aus, die die Arbeitswelt betreffen, wie z. B. Arbeitsgesetze, Rentenregelungen oder Arbeitssicherheit."}]'::jsonb, ''),
  ('oabeita', 'Oabeita', '', '', '', '', 'Arbeiter', '[{"kategorie": "jur.", "text": "\"Person, die eine körperliche oder handwerkliche Tätigkeit ausübt und im Rahmen eines Arbeitsverhältnisses gegen Lohn für einen Arbeitgeber arbeitet\""}, {"kategorie": "", "text": "Im Gegensatz zu [[Angestellten]], die oft in bürokratischen oder kaufmännischen Bereichen tätig sind, stehen bei Arbeitern oft manuelle oder technische Arbeiten im Vordergrund"}, {"kategorie": "", "text": "Arbeiter führen in der Regel Tätigkeiten aus, die körperliche Anstrengung erfordern oder in handwerklichen, industriellen oder technischen Berufen stattfinden, wie etwa in der Bauwirtschaft, der Produktion oder im Transportwesen"}, {"kategorie": "", "text": "Arbeiter werden oft auf Basis ihrer Arbeitsstunden entlohnt. Dies erfolgt häufig durch einen Stundenlohn oder Akkordlohn, der je nach geleisteter Arbeit berechnet wird"}, {"kategorie": "", "text": "Das Arbeitsverhältnis eines Arbeiters ist durch einen Arbeitsvertrag geregelt, in dem die Arbeitsbedingungen, der Lohn, die Arbeitszeit und andere Rechte und Pflichten festgelegt sind. Der Vertrag unterliegt in der Regel den Tarifverträgen, die für bestimmte Branchen oder Berufe gelten"}, {"kategorie": "", "text": "Im Gegensatz zu Angestellten, die oft in Bürojobs oder administrativen Tätigkeiten arbeiten, sind Arbeiter stärker in praktische und physische Aufgaben eingebunden. Die rechtliche Unterscheidung wird durch unterschiedliche Arbeits- und Sozialrechtsregelungen bestimmt, wie etwa unterschiedliche Bestimmungen für Urlaubsansprüche oder Krankheitszeiten"}, {"kategorie": "", "text": "Arbeiter sind häufig in [[Gewerkschaften]] organisiert, die ihre Interessen gegenüber den Arbeitgebern vertreten und Tarifverträge aushandeln. Diese regeln Löhne, Arbeitszeiten, Urlaub und andere arbeitsrechtliche Aspekte."}]'::jsonb, ''),
  ('pragmatisiirung', 'Pragmatisiirung', '', '', '', '', 'Pragmatisierung', '[{"kategorie": "jur.", "text": "\"rechtlicher Status, den ein Beamter im öffentlichen Dienst erhält, wenn er nach einer Probezeit endgültig in ein Beamtenverhältnis auf Lebenszeit übernommen wird\""}, {"kategorie": "", "text": "Mit der Pragmatisierung gehen besondere Rechte und Pflichten einher, die den Beamtenstatus dauerhaft sichern, darunter insbesondere Unkündbarkeit und der Anspruch auf eine Beamtenpension"}, {"kategorie": "", "text": "Ein pragmatisierter Beamter genießt Unkündbarkeit und kann nur unter außergewöhnlichen Umständen entlassen werden, wie bei schweren Dienstvergehen oder Verlust der Eignung. Dies bietet dem Beamten eine hohe Jobsicherheit"}, {"kategorie": "", "text": "Mit der Pragmatisierung kommen besondere Pflichten wie die strikte Gesetzestreue, Neutralität und Verschwiegenheitspflicht. Auf der anderen Seite genießen pragmatisierte Beamte besondere Rechte, wie den Anspruch auf eine Beamtenpension und besondere Versorgungsleistungen im Ruhestand"}, {"kategorie": "", "text": "Pragmatisierte Beamte haben keinen Anspruch auf die gesetzliche Rente, sondern erhalten eine Beamtenpension, die in der Regel höher ist und vom Staat gezahlt wird"}, {"kategorie": "", "text": "Zur Pragmatisierung müssen Beamte bestimmte Voraussetzungen erfüllen, wie das erfolgreiche Ableisten der Probezeit, eine positive Eignungsprüfung und die Einhaltung der gesetzlichen Altersgrenzen. Der Beamte muss sich zudem durch einwandfreies Verhalten und Leistungsfähigkeit auszeichnen."}]'::jsonb, ''),
  ('beaumta', 'Beaumta', '', '', '', '', 'Beamter', '[{"kategorie": "jur.", "text": "\"Person, die in einem öffentlichen Dienstverhältnis steht und für den [[Staat]] oder eine öffentliche Körperschaft arbeitet\""}, {"kategorie": "", "text": "Beamte sind in vielen Ländern, darunter auch Österreich und Deutschland, besonders verpflichtet, die Interessen des Staates zu vertreten und dabei gesetzliche Aufgaben zu erfüllen"}, {"kategorie": "", "text": "Sie genießen im Gegenzug besondere Rechte und Pflichten, die sich von Arbeitnehmern im privaten Sektor unterscheiden"}, {"kategorie": "", "text": "Ein Beamter steht in einem besonderen Dienst- und Treueverhältnis zu seinem Dienstherren, der in der Regel der Staat, eine Gemeinde oder eine andere öffentliche Einrichtung ist. Dieses Dienstverhältnis ist durch besondere Gesetze und Vorschriften geregelt"}, {"kategorie": "", "text": "Beamte sind zur Gesetzestreue verpflichtet, das heißt, sie müssen die geltenden Gesetze strikt beachten und in ihrer Tätigkeit den Staat oder die öffentliche Institution in besonderem Maße unterstützen"}, {"kategorie": "", "text": "Sie haben eine Treuepflicht gegenüber dem Staat und müssen ihre Aufgaben neutral und im öffentlichen Interesse wahrnehmen.\nIn vielen Ländern besteht eine besondere Verschwiegenheitspflicht sowie das Verbot der Teilnahme an Streiks"}, {"kategorie": "", "text": "Im Gegenzug haben Beamte besondere Rechte, wie einen besonderen Kündigungsschutz, das Recht auf Alimentation (besoldete Versorgung), also eine stabile und sichere Bezahlung, sowie eine Pension nach dem Ausscheiden aus dem Dienst"}, {"kategorie": "", "text": "Sie erhalten im Gegensatz zu Angestellten keine gesetzliche Rente, sondern eine Beamtenpension, die durch den Staat getragen wird"}, {"kategorie": "", "text": "Ein wesentlicher Vorteil des Beamtenstatus ist die Unkündbarkeit nach der Verbeamtung auf Lebenszeit ([[Pragmatisierung]]), was eine langfristige Job- und Einkommenssicherheit bietet. Nur in seltenen Fällen, wie bei schwerwiegenden Verstößen gegen Dienstpflichten, können Beamte aus dem Dienst entlassen werden"}, {"kategorie": "", "text": "Beamte erfüllen meist hoheitliche Aufgaben, die der Staat oder die öffentliche Verwaltung selbst ausführen muss. Dazu zählen etwa Tätigkeiten in der [[Polizei]], der [[Justiz]], der [[Finanzverwaltung]] oder im Bildungswesen"}, {"kategorie": "", "text": "Beamte sind im Gegensatz zu Angestellten des öffentlichen Dienstes nicht nach dem allgemeinen Arbeitsrecht angestellt, sondern unterliegen speziellen Beamtengesetzen. Das Arbeitsrecht gilt für Beamte nur in Teilen."}]'::jsonb, ''),
  ('sozialoabeita', 'Sozialoabeita', '', '', '', '', 'Sozialarbeiter', '[{"kategorie": "jur.", "text": "\"ausgebildeter Fachmann, der Menschen in sozialen Notlagen unterstützt und ihnen hilft, ihre Lebenssituation zu verbessern\""}, {"kategorie": "", "text": "Sozialarbeiter arbeiten in verschiedenen Bereichen wie Sozialdiensten, Bildungseinrichtungen, Gesundheitswesen, Jugendarbeit, [[Strafvollzug]] oder Familienhilfe und bieten sowohl Beratung als auch praktische Unterstützung"}, {"kategorie": "", "text": "Sozialarbeiter fördern die Wiedereingliederung von Menschen in die Gesellschaft, z. B. nach Haftstrafen, Suchtbehandlungen oder bei der Integration von Migranten. Sie helfen dabei, soziale Barrieren zu überwinden und ein selbstständiges Leben aufzubauen"}, {"kategorie": "", "text": "Sozialarbeiter vermitteln Zugang zu sozialen Leistungen und Hilfsangeboten, z. B. zu Wohnraum, finanziellen Unterstützungen oder Therapien. Sie kooperieren mit Ämtern, Gemeinden und anderen Institutionen, um den Betroffenen die nötigen Ressourcen bereitzustellen"}, {"kategorie": "", "text": "In Krisensituationen wie psychischen Notfällen, Suchtproblemen oder häuslicher Gewalt bieten Sozialarbeiter schnelle Hilfe und setzen sich für eine Verbesserung der Situation ein, indem sie den Zugang zu professionellen Hilfsangeboten oder Notunterkünften organisieren."}]'::jsonb, ''),
  ('bewaeaerungshoeoefa', 'Bewäärungshööfa', '', '', '', '', 'Bewährungshelfer', '[{"kategorie": "jur.", "text": "\"speziell ausgebildeter [[Sozialarbeiter]] oder Beamter, der im Rahmen des [[Strafvollzugs]] für die Betreuung und Überwachung von Personen zuständig ist, die auf [[Bewährung]] entlassen wurden oder deren Strafe zur Bewährung ausgesetzt wurde\""}, {"kategorie": "", "text": "Der Bewährungshelfer unterstützt den Verurteilten während der [[Bewährungszeit]], überwacht die Einhaltung der Auflagen und hilft bei der Resozialisierung"}, {"kategorie": "", "text": "Der Bewährungshelfer überwacht, ob der Verurteilte die ihm vom Gericht auferlegten [[Bewährungsauflagen]] erfüllt. Dazu gehören z. B. regelmäßige Meldungen, Therapieauflagen, Arbeitsauflagen oder Kontaktverbote"}, {"kategorie": "", "text": "Neben der Überwachung bietet der Bewährungshelfer dem Verurteilten soziale Unterstützung. Er hilft bei der Wiedereingliederung in die Gesellschaft, z. B. bei der Jobsuche, bei der Regelung von Schulden oder beim Aufbau eines stabilen sozialen Umfelds"}, {"kategorie": "", "text": "Der Verurteilte muss sich regelmäßig mit dem Bewährungshelfer treffen. Diese Treffen dienen dazu, den Fortschritt des Verurteilten zu bewerten und sicherzustellen, dass er die Bedingungen der Bewährung einhält"}, {"kategorie": "", "text": "Der Bewährungshelfer erstattet regelmäßig Bericht an das zuständige Gericht über den Verlauf der Bewährung. Wenn der Verurteilte die Auflagen nicht einhält oder straffällig wird, kann der Bewährungshelfer das Gericht informieren, was zu einem Widerruf der Bewährung führen kann."}]'::jsonb, ''),
  ('bewaeaerung', 'Bewäärung', '', '', '', '', 'Bewährung', '[{"kategorie": "jur.", "text": "\"rechtliche Maßnahme, bei der eine [[Freiheitsstrafe]] oder ein Teil davon ausgesetzt wird, sodass der Verurteilte die [[Strafe]] nicht im Gefängnis absitzen muss, sondern unter bestimmten Auflagen und unter Überwachung eine [[Bewährungszeit]] in Freiheit verbringt\""}, {"kategorie": "", "text": "Während dieser Zeit muss sich der Verurteilte an gesetzliche Vorgaben und spezifische [[Bewährungsauflagen]] halten"}, {"kategorie": "", "text": "Ziel der Bewährung ist es, die Resozialisierung des Verurteilten zu fördern und ihn in die Gesellschaft wiedereinzugliedern"}, {"kategorie": "", "text": "Bei Strafe auf Bewährung wird die verhängte Freiheitsstrafe ausgesetzt, d. h., der Verurteilte muss nicht ins Gefängnis, wenn er sich während der festgelegten Bewährungszeit gut führt und keine neuen Straftaten begeht"}, {"kategorie": "", "text": "Bei der [[bedingten]] Entlassung aus einer bereits angetretenen Haftstrafe wird der Verurteilte vorzeitig entlassen, wenn er sich während der restlichen Bewährungszeit bewährt"}, {"kategorie": "", "text": "Die [[Bewährungszeit]] ist ein festgelegter Zeitraum (in der Regel ein bis fünf Jahre), in dem der Verurteilte zeigen muss, dass er keine weiteren Straftaten begeht und sich an die Auflagen hält"}, {"kategorie": "", "text": "Während der Bewährungszeit müssen bestimmte Auflagen erfüllt werden, wie z. B. regelmäßige Meldungen bei einem [[Bewährungshelfer]], Arbeitsauflagen oder der Besuch von Therapien. Diese Auflagen sollen zur Resozialisierung und Vermeidung erneuter Straftaten beitragen"}, {"kategorie": "", "text": "Der Verurteilte wird während der Bewährungszeit in der Regel von einem Bewährungshelfer betreut, der seinen Fortschritt überwacht und darauf achtet, dass die Auflagen eingehalten werden"}, {"kategorie": "", "text": "Verstößt der Verurteilte gegen die [[Bewährungsauflagen]] oder begeht er während der Bewährungszeit eine neue Straftat, kann das Gericht die Bewährung widerrufen. In diesem Fall muss der Verurteilte die ursprünglich verhängte Strafe (oder den restlichen Teil der Strafe) im Gefängnis verbüßen"}, {"kategorie": "", "text": "Das Ziel der Bewährung ist es, dem Verurteilten die Chance zu geben, sich ohne Haftstrafe zu resozialisieren und sich wieder in die Gesellschaft zu integrieren, ohne dass der [[Strafvollzug]] den Prozess der Wiedereingliederung erschwert."}]'::jsonb, ''),
  ('bewaehrungsauflogn', 'Bewährungsauflogn', '', '', '', '', 'Bewährungsauflagen', '[{"kategorie": "jur.", "text": "\"Verpflichtungen und Bedingungen, die ein Verurteilter im Rahmen einer [[bedingten]] Entlassung oder einer [[Strafe]] auf Bewährung erfüllen muss, um seine vorzeitige Entlassung aus der Haft oder den [[Strafaufschub]] nicht zu gefährden\""}, {"kategorie": "", "text": "Diese Auflagen dienen dazu, den Verurteilten während der [[Bewährungszeit]] zu überwachen und seine Resozialisierung in die Gesellschaft zu unterstützen"}, {"kategorie": "", "text": "Der Verurteilte muss sich an die von [[Gericht]] oder [[Bewährungshelfern]] auferlegten Bedingungen halten. Diese sollen sicherstellen, dass er nicht erneut straffällig wird und sich verantwortungsvoll verhält"}, {"kategorie": "", "text": "Der Verurteilte muss sich regelmäßig bei einem Bewährungshelfer oder der zuständigen Behörde melden. Außerdem kann der Verurteilte angewiesen werden, seinen Wohnort nicht zu wechseln, oder eine bestimmte Wohnsitzauflage erhalten. In vielen Fällen wird ein Verbot des Konsums von Drogen oder Alkohol auferlegt, insbesondere bei Straftaten im Zusammenhang mit Suchtmitteln. Der Verurteilte kann auch verpflichtet werden, an einer Therapie, einer Suchtberatung oder einem Anti-Gewalt-Training teilzunehmen"}, {"kategorie": "", "text": "Die Auflagen gelten für die gesamte Dauer der [[Bewährungszeit]] und werden von den zuständigen Behörden oder einem [[Bewährungshelfer]] überwacht. Diese haben die Aufgabe, den Fortschritt des Verurteilten zu kontrollieren und über eventuelle Verstöße zu berichten"}, {"kategorie": "", "text": "Die Auflagen sollen dem Verurteilten helfen, sich an gesellschaftliche Normen anzupassen, seine Verhaltensweisen zu ändern und sicherzustellen, dass er keine neuen Straftaten begeht"}, {"kategorie": "", "text": "Verstößt der Verurteilte gegen die Bewährungsauflagen, kann das Gericht die Bedingung der Bewährung widerrufen. Das bedeutet, dass er entweder in die Haft zurückkehren muss (bei [[bedingter]] Entlassung) oder die ursprünglich ausgesetzte Strafe antreten muss (bei [[Bewährungsstrafe]])."}]'::jsonb, ''),
  ('hoftschdrof', 'Hoftschdrof', '', '', '', '', 'Haftstrafe', '[{"kategorie": "jur.", "text": "\"strafrechtliche Sanktion, bei der eine Person durch ein rechtskräftiges [[Gerichtsurteil]] für eine bestimmte Zeit ihrer persönlichen Freiheit beraubt und in einer [[Justizanstalt]] inhaftiert wird\""}, {"kategorie": "", "text": "Sie ist die schwerste Form der [[Strafe]] im [[Strafrecht]] und wird für besonders schwerwiegende [[Vergehen]] oder [[Verbrechen]] verhängt"}, {"kategorie": "", "text": "Eine Freiheitsstrafe wird von einem [[Gericht]] nach einer Verurteilung in einem Strafverfahren verhängt. Der Verurteilte muss die festgelegte Strafe in einer Justizanstalt verbüßen"}, {"kategorie": "", "text": "Die Dauer der Freiheitsstrafe kann von wenigen Monaten bis hin zu lebenslanger Haft reichen, je nach Schwere der [[Straftat]] und den gesetzlichen Vorgaben. In manchen Fällen kann eine Freiheitsstrafe auch zur Bewährung ausgesetzt werden"}, {"kategorie": "", "text": "Je nach Schwere des Delikts kann die Freiheitsstrafe in unterschiedlichen Haftformen vollzogen werden, z. B. im [[offenen]] Vollzug oder im [[geschlossenen]] Vollzug, der strikteren Sicherheitsvorkehrungen unterliegt"}, {"kategorie": "", "text": "Neben der Strafe für das begangene Verbrechen ist ein wichtiges Ziel der Freiheitsstrafe die Resozialisierung des Verurteilten, also die Wiedereingliederung in die Gesellschaft nach der Haft. Dazu werden in den Justizanstalten Programme zur Bildung, Arbeit und Therapie angeboten"}, {"kategorie": "", "text": "Die Freiheitsstrafe muss verhältnismäßig sein, d. h. sie muss im Verhältnis zur Schwere der Tat stehen und darf nicht willkürlich sein. Sie wird nur verhängt, wenn dies gesetzlich vorgesehen ist und mildere Strafen nicht angemessen sind"}, {"kategorie": "", "text": "In besonders schweren Fällen, wie bei Mord oder schwerwiegenden Gewaltverbrechen, kann eine [[lebenslange]] Freiheitsstrafe verhängt werden, bei der der Verurteilte grundsätzlich den Rest seines Lebens in Haft verbringen muss. Allerdings besteht oft die Möglichkeit, nach einer Mindesthaftzeit eine vorzeitige Entlassung zu beantragen."}]'::jsonb, ''),
  ('freiheitsschdrof', 'Freiheitsschdrof', '', '', '', '', 'Freiheitsstrafe', '[{"kategorie": "jur.", "text": "\"strafrechtliche Sanktion, bei der eine Person durch ein rechtskräftiges [[Gerichtsurteil]] für eine bestimmte Zeit ihrer persönlichen Freiheit beraubt und in einer [[Justizanstalt]] inhaftiert wird\""}, {"kategorie": "", "text": "Sie ist die schwerste Form der [[Strafe]] im [[Strafrecht]] und wird für besonders schwerwiegende [[Vergehen]] oder [[Verbrechen]] verhängt"}, {"kategorie": "", "text": "Eine Freiheitsstrafe wird von einem [[Gericht]] nach einer Verurteilung in einem Strafverfahren verhängt. Der Verurteilte muss die festgelegte Strafe in einer Justizanstalt verbüßen"}, {"kategorie": "", "text": "Die Dauer der Freiheitsstrafe kann von wenigen Monaten bis hin zu lebenslanger Haft reichen, je nach Schwere der [[Straftat]] und den gesetzlichen Vorgaben. In manchen Fällen kann eine Freiheitsstrafe auch zur Bewährung ausgesetzt werden"}, {"kategorie": "", "text": "Je nach Schwere des Delikts kann die Freiheitsstrafe in unterschiedlichen Haftformen vollzogen werden, z. B. im [[offenen]] Vollzug oder im [[geschlossenen]] Vollzug, der strikteren Sicherheitsvorkehrungen unterliegt"}, {"kategorie": "", "text": "Neben der Strafe für das begangene Verbrechen ist ein wichtiges Ziel der Freiheitsstrafe die Resozialisierung des Verurteilten, also die Wiedereingliederung in die Gesellschaft nach der Haft. Dazu werden in den Justizanstalten Programme zur Bildung, Arbeit und Therapie angeboten"}, {"kategorie": "", "text": "Die Freiheitsstrafe muss verhältnismäßig sein, d. h. sie muss im Verhältnis zur Schwere der Tat stehen und darf nicht willkürlich sein. Sie wird nur verhängt, wenn dies gesetzlich vorgesehen ist und mildere Strafen nicht angemessen sind"}, {"kategorie": "", "text": "In besonders schweren Fällen, wie bei Mord oder schwerwiegenden Gewaltverbrechen, kann eine [[lebenslange]] Freiheitsstrafe verhängt werden, bei der der Verurteilte grundsätzlich den Rest seines Lebens in Haft verbringen muss. Allerdings besteht oft die Möglichkeit, nach einer Mindesthaftzeit eine vorzeitige Entlassung zu beantragen."}]'::jsonb, ''),
  ('hauptvahaundlung', 'Hauptvahaundlung', '', '', '', '', 'Hauptverhandlung', '[{"kategorie": "jur.", "text": "\"zentraler öffentlicher Verfahrensabschnitt in einem [[Strafprozess]], bei dem vor [[Gericht]] die Schuldfrage geklärt und gegebenenfalls die Strafe festgelegt wird\""}, {"kategorie": "", "text": "In der Hauptverhandlung werden die Ergebnisse der Ermittlungen präsentiert, Zeugen vernommen und Beweise geprüft. Am Ende entscheidet das Gericht über Schuld oder Unschuld des Angeklagten und spricht ein [[Urteil]]"}, {"kategorie": "", "text": "Die Hauptverhandlung ist grundsätzlich öffentlich, um Transparenz und Fairness zu gewährleisten. In bestimmten Fällen, wie z. B. bei jugendlichen Angeklagten oder aus Gründen der Sicherheit, kann die [[Öffentlichkeit]] ausgeschlossen werden"}, {"kategorie": "", "text": "Die Hauptverhandlung beginnt mit der Verlesung der [[Anklageschrift]], in der die Staatsanwaltschaft die Vorwürfe gegen den Angeklagten darlegt"}, {"kategorie": "", "text": "Danach werden Zeugen, Sachverständige und Beweise gehört oder präsentiert. Sowohl die [[Staatsanwaltschaft]] als auch die [[Verteidigung]] haben die Möglichkeit, Zeugen zu befragen und Beweise einzubringen. Der Angeklagte hat das Recht, sich zu den Vorwürfen zu äußern oder zu schweigen"}, {"kategorie": "", "text": "An der Hauptverhandlung sind mehrere Parteien beteiligt: das [[Gericht]] ([[Richter]] oder [[Schöffen]]/[[Geschworene]]), die [[Staatsanwaltschaft]], der [[Angeklagte]] und dessen [[Verteidiger]] sowie in manchen Fällen [[Nebenkläger]] (z. B. Opfer von Straftaten)"}, {"kategorie": "", "text": "Die Beweisaufnahme ist der Kern der [[Hauptverhandlung]]. Es werden alle relevanten Beweise und Aussagen von [[Zeugen]] oder [[Sachverständigen]] geprüft, um festzustellen, ob der Angeklagte die ihm zur Last gelegte Tat begangen hat"}, {"kategorie": "", "text": "Nach Abschluss der [[Beweisaufnahme]] halten die Staatsanwaltschaft und die Verteidigung ihre [[Plädoyers]]. In diesen fasst jede Seite ihre Sicht des Falls zusammen und schlägt eine Entscheidung über Schuld und Strafe vor"}, {"kategorie": "", "text": "Am Ende der Hauptverhandlung entscheidet das Gericht über die Schuld oder Unschuld des Angeklagten und verkündet das [[Urteil]]. Wird der Angeklagte für schuldig befunden, legt das Gericht auch die Strafe fest"}, {"kategorie": "", "text": "Wenn das Urteil rechtskräftig ist, kann es vollstreckt werden, andernfalls besteht die Möglichkeit, [[Rechtsmittel]] einzulegen"}, {"kategorie": "", "text": "Nach der Hauptverhandlung können die Parteien, also die Staatsanwaltschaft und der Angeklagte, gegen das Urteil Rechtsmittel einlegen, etwa eine [[Berufung]] oder [[Nichtigkeitsbeschwerde]], um eine Überprüfung der Entscheidung zu erreichen."}]'::jsonb, ''),
  ('unschuidsvamutung', 'Unschuidsvamutung', '', '', '', '', 'Unschuldsvermutung', '[{"kategorie": "jur.", "text": "\"grundlegendes Rechtsprinzip, das besagt, dass eine Person, die einer [[Straftat]] beschuldigt wird, bis zum rechtskräftigen Beweis ihrer Schuld als unschuldig gilt\""}, {"kategorie": "", "text": "Dieses Prinzip stellt sicher, dass niemand ohne ein faires [[Gerichtsverfahren]] und ohne hinreichenden Beweis für schuldig erklärt werden darf"}, {"kategorie": "", "text": "Die Unschuldsvermutung ist ein zentraler Bestandteil des [[Rechtsstaats]] und ist in vielen nationalen und internationalen [[Rechtsordnungen]] verankert, unter anderem in der [[Europäischen]] Menschenrechtskonvention (Artikel 6). Sie soll sicherstellen, dass jeder Beschuldigte ein faires Verfahren erhält"}, {"kategorie": "", "text": "Die [[Beweislast]] liegt bei der [[Staatsanwaltschaft]]. Das bedeutet, dass die Schuld des [[Beschuldigten]] im Verfahren eindeutig nachgewiesen werden muss. Der Beschuldigte selbst muss nicht seine Unschuld beweisen"}, {"kategorie": "", "text": "Die Unschuldsvermutung gilt bis zu einer rechtskräftigen Verurteilung. Der Beschuldigte wird erst durch ein gerichtliches [[Urteil]], das alle [[Rechtsmittel]] überstanden hat, für schuldig erklärt"}, {"kategorie": "", "text": "Die Unschuldsvermutung schützt den Beschuldigten vor Vorverurteilungen durch [[Medien]] oder die [[Öffentlichkeit]]. Solange kein rechtskräftiges Urteil vorliegt, darf der Beschuldigte nicht als schuldig behandelt oder bezeichnet werden."}]'::jsonb, ''),
  ('aunzeig', 'Aunzeig', '', '', '', '', 'Anzeige', '[{"kategorie": "jur.", "text": "\"Mitteilung, Meldung oder Erklärung an eine zuständige Behörde, insbesondere an die [[Polizei]] oder [[Staatsanwaltschaft]], durch die eine vermutete Straftat oder ein rechtswidriges Verhalten bekannt gemacht wird\""}, {"kategorie": "", "text": "Ziel der Anzeige ist es, die Ermittlung und gegebenenfalls die [[Strafverfolgung]] einzuleiten"}, {"kategorie": "", "text": "Eine Anzeige kann schriftlich, mündlich oder auch online bei den zuständigen Behörden erstattet werden. Es ist nicht erforderlich, dass die anzeigende Person selbst betroffen ist; auch Dritte können eine Anzeige erstatten"}, {"kategorie": "", "text": "Nach der Anzeige prüft die Behörde, ob ein [[Anfangsverdacht]] für eine [[Straftat]] vorliegt. Besteht dieser Verdacht, leiten die [[Ermittlungsbehörden]] ein [[Ermittlungsverfahren]] ein, um den Sachverhalt zu klären"}, {"kategorie": "", "text": "In vielen Fällen besteht keine Pflicht, eine Anzeige zu erstatten, außer bei besonders schweren Straftaten (z. B. Mord). Jedoch kann das Unterlassen einer Anzeige in bestimmten Fällen auch strafrechtlich relevant sein, insbesondere bei der Nichtanzeige geplanter Verbrechen"}, {"kategorie": "", "text": "In vielen Ländern, einschließlich Österreich, ist auch eine anonyme Anzeige möglich. In solchen Fällen prüft die Behörde den gemeldeten Sachverhalt, ohne die Identität des Anzeigenden zu kennen."}]'::jsonb, ''),
  ('schrofvafoigung', 'Schrofvafoigung', '', '', '', '', 'Strafverfolgung', '[{"kategorie": "jur.", "text": "\"Prozess, bei dem der [[Staat]] durch die [[Staatsanwaltschaft]] und die Strafverfolgungsbehörden (wie Polizei und Ermittlungsbehörden) gegen Personen vorgeht, die einer Straftat verdächtigt oder beschuldigt werden\""}, {"kategorie": "", "text": "Ziel der Strafverfolgung ist es, Straftaten aufzuklären, die Verantwortlichen zur Rechenschaft zu ziehen und sie gegebenenfalls vor Gericht zu stellen, um eine Strafe zu verhängen"}, {"kategorie": "", "text": "Die Strafverfolgung beginnt mit der Ermittlung einer Straftat, meist durch die Polizei oder andere Ermittlungsbehörden. Dies kann durch eine [[Strafanzeige]], Eigeninitiative der Behörden oder durch Hinweise von Dritten ausgelöst werden"}, {"kategorie": "", "text": "Die Staatsanwaltschaft leitet die Strafverfolgung und entscheidet, ob [[Anklage]] erhoben wird. Sie sammelt Beweise, beauftragt die Ermittlungsbehörden und vertritt den Staat in einem späteren Strafverfahren"}, {"kategorie": "", "text": "Im Rahmen der Strafverfolgung werden Beweise gesammelt, Zeugen befragt und Verdächtige vernommen. Es kann zu Zwangsmaßnahmen wie Durchsuchungen, Beschlagnahmungen oder [[Untersuchungshaft]] kommen, wenn dies zur Sicherung des Verfahrens notwendig ist"}, {"kategorie": "", "text": "Nach Abschluss der Ermittlungen entscheidet die Staatsanwaltschaft, ob die Anklage erhoben wird. Wenn genügend Beweise vorliegen, wird der Fall vor ein Strafgericht gebracht. Andernfalls kann das Verfahren eingestellt werden"}, {"kategorie": "", "text": "Die Strafverfolgung unterliegt den Grundsätzen des [[Rechtsstaats]]. Dazu gehören die Unschuldsvermutung (bis zur Verurteilung) und das Recht des Beschuldigten auf eine faire Verteidigung"}, {"kategorie": "", "text": "Die Strafverfolgung bezieht sich auf den Prozess der Aufklärung und Verfolgung einer Straftat bis zur [[Anklageerhebung]] und einem [[Urteil]], währenddem die [[Strafvollstreckung]] nach einem rechtskräftigen [[Urteil]] den Vollzug der Strafe (z. B. Freiheitsstrafe) beinhaltet."}]'::jsonb, ''),
  ('schdrofvoizug', 'Schdrofvoizug', '', '', '', '', 'Strafvollzug', '[{"kategorie": "jur.", "text": "\"Durchführung und Vollstreckung von Freiheitsstrafen und anderen strafrechtlichen Sanktionen, die durch ein rechtskräftiges [[Gerichtsurteil]] verhängt wurden\""}, {"kategorie": "", "text": "Der Strafvollzug dient der Umsetzung einer vom Gericht verhängten Freiheitsstrafe oder anderer strafrechtlicher Sanktionen. Die Verurteilten werden in eine [[Justizanstalt]] (Gefängnis) eingewiesen, um dort ihre Strafe zu verbüßen"}, {"kategorie": "", "text": "Ein zentrales Ziel des Strafvollzugs ist die Resozialisierung der Insassen. Dabei werden Programme zur Bildung, Arbeit, Therapie und Verhaltensänderung angeboten, um die Wiedereingliederung in die Gesellschaft nach der Haft zu fördern"}, {"kategorie": "", "text": "Der Strafvollzug stellt sicher, dass der Verurteilte während der Haftzeit unter strikter Überwachung steht und die Haftordnung eingehalten wird, um Flucht oder Unruhen zu verhindern"}, {"kategorie": "", "text": "Es gibt verschiedene Formen des Strafvollzugs, wie z.B. den offenen Vollzug, bei dem die Insassen unter gelockerten Bedingungen leben, oder den geschlossenen Vollzug, der strikte Sicherheitsmaßnahmen umfasst. Auch der Jugendstrafvollzug und der Vollzug von lebenslangen Strafen gehören dazu"}, {"kategorie": "", "text": "Verurteilte haben im Strafvollzug bestimmte Rechte, wie z.B. Besuchsrechte oder das Recht auf medizinische Versorgung, aber auch Pflichten, wie die Teilnahme an Arbeitsmaßnahmen oder die Einhaltung der Anstaltsregeln"}, {"kategorie": "", "text": "Der Strafvollzug endet entweder mit der Verbüßung der gesamten Strafe oder einer vorzeitigen Entlassung auf Bewährung, wenn der Häftling bestimmte Voraussetzungen erfüllt."}]'::jsonb, ''),
  ('schdrofhoft', 'Schdrofhoft', '', '', '', '', 'Strafhaft', '[{"kategorie": "jur.", "text": "\"Freiheitsentziehung einer Person, die aufgrund eines rechtskräftigen Strafurteils zu einer Freiheitsstrafe verurteilt wurde\""}, {"kategorie": "", "text": "Die Strafhaft wird nach einem rechtskräftigen [[Gerichtsurteil]] angeordnet, wenn die Freiheitsstrafe endgültig verhängt wurde und keine Rechtsmittel mehr möglich sind. Sie betrifft Verurteilte, die eine Freiheitsstrafe antreten müssen"}, {"kategorie": "", "text": "Die Strafhaft dient der Verbüßung der vom Gericht verhängten Strafe. Der Verurteilte wird in einer [[Justizanstalt]] untergebracht, wo er die festgelegte Dauer der Strafe absitzt. Dies kann von wenigen Monaten bis zu lebenslanger Haft reichen"}, {"kategorie": "", "text": "Während der Strafhaft unterliegt der Verurteilte den Regeln des [[Strafvollzugs]]. Der Haftvollzug zielt neben der Bestrafung auch auf die Resozialisierung ab, indem den Insassen Programme zur Bildung, Arbeit und Therapie angeboten werden"}, {"kategorie": "", "text": "Je nach Schwere der Straftat und Persönlichkeit des Verurteilten kann die Strafhaft in verschiedenen Formen vollzogen werden, z. B. in offenen oder geschlossenen Haftanstalten. Besonders schwere Fälle können in Hochsicherheitsgefängnissen verbüßt werden"}, {"kategorie": "", "text": "Die Strafhaft endet, wenn die festgelegte Strafe vollständig verbüßt wurde oder wenn der Verurteilte vorzeitig, z. B. durch gutes Verhalten, auf Bewährung entlassen wird."}]'::jsonb, ''),
  ('untasuchungshoft', 'Untasuchungshoft', '', '', '', '', 'Untersuchungshaft', '[{"kategorie": "jur.", "text": "\"vorläufige Freiheitsentziehung, die im Rahmen eines [[Strafverfahrens]] gegen eine Person verhängt wird, die einer Straftat verdächtigt wird\""}, {"kategorie": "", "text": "Die Untersuchungshaft dient der Sicherstellung des Strafverfahrens. Sie verhindert, dass der Beschuldigte sich der Strafverfolgung durch Flucht entzieht, Beweise vernichtet oder Zeugen beeinflusst. Sie kann auch angeordnet werden, um die Begehung weiterer Straftaten zu verhindern"}, {"kategorie": "", "text": "Die Anordnung der Untersuchungshaft erfordert einen dringenden Tatverdacht gegen den Beschuldigten sowie das Vorliegen eines besonderen Haftgrundes. Diese Haftgründe können sein: (i) Fluchtgefahr (wenn zu befürchten ist, dass der Beschuldigte das Land verlässt oder sich anderweitig dem Verfahren entzieht), (ii) Verdunkelungsgefahr (wenn die Gefahr besteht, dass der Beschuldigte Beweismittel vernichtet oder Zeugen beeinflusst), (iii) Tatbegehungsgefahr (wenn die Wahrscheinlichkeit besteht, dass der Beschuldigte weitere Straftaten begeht)"}, {"kategorie": "", "text": "Die Untersuchungshaft darf nicht unbegrenzt andauern und muss regelmäßig vom Gericht überprüft werden. Es gibt gesetzliche Fristen, innerhalb derer das Verfahren vorangetrieben werden muss. Bei schweren Straftaten kann die Untersuchungshaft aber länger dauern"}, {"kategorie": "", "text": "Gegen die Anordnung der Untersuchungshaft kann der Beschuldigte Rechtsmittel einlegen, wie z. B. einen Antrag auf Haftprüfung oder eine [[Beschwerde]]. Das Gericht überprüft dann, ob die Haft weiterhin gerechtfertigt ist"}, {"kategorie": "", "text": "Die Untersuchungshaft unterscheidet sich von der [[Strafhaft]] dadurch, dass sie nicht eine bereits verhängte Strafe vollstreckt, sondern nur dazu dient, das Strafverfahren sicherzustellen. Sie erfolgt vor einem rechtskräftigen [[Urteil]], und der Beschuldigte gilt weiterhin als unschuldig bis zum Beweis seiner Schuld."}]'::jsonb, ''),
  ('justizwochebeaumta', 'Justizwochebeaumta', '', '', '', '', 'Justizwachebeamter', '[{"kategorie": "jur.", "text": "\"Bediensteter des Justizwachdienstes in Österreich, der in [[Justizanstalten]] (Gefängnissen) für die Überwachung, Betreuung und Sicherheit der Insassen verantwortlich ist\""}, {"kategorie": "", "text": "Ein Justizwachebeamter überwacht und bewacht die Insassen der Justizanstalt, um Fluchtversuche oder Verstöße gegen die Haftordnung zu verhindern. Er sorgt für die Sicherheit sowohl der Häftlinge als auch des Personals"}, {"kategorie": "", "text": "Neben der Sicherheitsüberwachung trägt der Justizwachebeamte zur Betreuung der Häftlinge bei. Er stellt sicher, dass die Hausordnung eingehalten wird, und sorgt für einen geordneten Ablauf von Arbeits- und Freizeitaktivitäten der Insassen"}, {"kategorie": "", "text": "Justizwachebeamte begleiten Insassen zu Gerichtsterminen, Arztbesuchen oder in andere Einrichtungen und sind für deren sicheren Transport verantwortlich"}, {"kategorie": "", "text": "Justizwachebeamte erhalten eine umfassende Ausbildung, die neben sicherheitstechnischen auch rechtliche und soziale Kompetenzen vermittelt. Sie müssen in der Lage sein, Konflikte zu deeskalieren, Fluchtversuche zu verhindern und den Haftalltag professionell zu organisieren."}]'::jsonb, ''),
  ('justizwoch', 'Justizwoch', '', '', '', '', 'Justizwache', '[{"kategorie": "jur.", "text": "\"Sicherheits- und Ordnungsdienst in österreichischen [[Justizanstalten]] (Gefängnissen)\""}, {"kategorie": "", "text": "Die Justizwache stellt die Sicherheit innerhalb der Justizanstalten sicher. Dazu gehört die Bewachung der Insassen, die Verhinderung von Fluchtversuchen und die Überwachung der Einhaltung von Haftregeln"}, {"kategorie": "", "text": "Justizwachebeamte kümmern sich auch um die Verwaltung des Haftalltags. Sie überwachen den Tagesablauf, die Arbeits- und Freizeitaktivitäten der Häftlinge und sorgen für geordnete Abläufe. Sie sind auch Ansprechpartner für Insassen und tragen zur Betreuung bei, indem sie Konflikte regeln und die Einhaltung der Disziplin sichern"}, {"kategorie": "", "text": "Die Justizwache ist auch für den Transport von Häftlingen zu Gerichtsterminen, Krankenhäusern oder anderen Orten zuständig und stellt dabei deren Sicherheit sicher"}, {"kategorie": "", "text": "Justizwachebeamte sind ausgebildet, bei Notfällen wie Unruhen, Fluchtversuchen, Bränden oder anderen Gefährdungssituationen schnell zu handeln und diese zu bewältigen."}]'::jsonb, ''),
  ('justizaunschdoit', 'Justizaunschdoit', '', '', '', '', 'Justizanstalt', '[{"kategorie": "jur.", "text": "\"Einrichtung in Österreich, in der Personen, die zu einer Freiheitsstrafe verurteilt wurden oder sich in [[Untersuchungshaft]] befinden, untergebracht sind\""}, {"kategorie": "", "text": "In einer Justizanstalt werden Personen, die rechtskräftig zu einer Freiheitsstrafe verurteilt wurden, inhaftiert. Hier verbüßen sie die ihnen auferlegte Strafe, abhängig von der Dauer der Verurteilung"}, {"kategorie": "", "text": "Justizanstalten beherbergen auch Personen, die sich in [[Untersuchungshaft]] befinden, das heißt, Personen, die einer Straftat beschuldigt sind und auf ihr Gerichtsverfahren warten. Diese Haft dient der Sicherstellung, dass der Beschuldigte nicht flieht oder Beweise vernichtet"}, {"kategorie": "", "text": "Es gibt verschiedene Arten von Justizanstalten, je nach Art und Schwere der Straftat, dem Gefährdungsgrad des Häftlings und der Dauer der Haft. Dazu zählen z. B. Anstalten für Jugendliche, Frauengefängnisse und Hochsicherheitsgefängnisse"}, {"kategorie": "", "text": "Neben der Verwahrung der Insassen zielt eine Justizanstalt auch auf die Resozialisierung der Häftlinge ab. Inhaftierte können an Bildungsprogrammen, Therapien oder Arbeitsmaßnahmen teilnehmen, um ihre Wiedereingliederung in die Gesellschaft nach der Haftstrafe zu fördern"}, {"kategorie": "", "text": "Justizanstalten werden vom österreichischen Justizministerium verwaltet und unterliegen der staatlichen Kontrolle. Die Justizwache ist für die Sicherheit und den Betrieb innerhalb der Anstalten zuständig."}]'::jsonb, ''),
  ('bewaehrungsschdrof', 'Bewährungsschdrof', '', '', '', '', 'Bewährungsstrafe', '[{"kategorie": "jur.", "text": "\" Freiheitsstrafe, die vom Gericht bedingt verhängt wird, das heißt, sie wird nicht sofort vollzogen\""}, {"kategorie": "", "text": "Bei einer Bewährungsstrafe wird die Verhängung oder der Vollzug einer Freiheitsstrafe ausgesetzt, unter der Bedingung, dass der Verurteilte sich innerhalb einer bestimmten Bewährungszeit (auch Probezeit genannt) straffrei verhält"}, {"kategorie": "", "text": "Die Dauer der Bewährungszeit (Probezeit) wird vom Gericht festgelegt und beträgt in der Regel zwischen ein und fünf Jahren. Während dieser Zeit wird das Verhalten des Verurteilten überwacht"}, {"kategorie": "", "text": "Das Gericht kann dem Verurteilten Auflagen und Weisungen erteilen, die er während der Bewährungszeit zu erfüllen hat, z. B. die Teilnahme an einer Therapie, soziale Dienste oder Meldepflichten. Die Einhaltung dieser Bedingungen ist Voraussetzung für den Erfolg der Bewährung"}, {"kategorie": "", "text": "Das Ziel der Bewährungsstrafe ist es, dem Verurteilten eine zweite Chance zu geben und ihn zu einer straffreien Lebensführung zu motivieren, ohne ihn ins Gefängnis zu schicken. Sie soll zur Resozialisierung beitragen und eine positive Integration in die Gesellschaft fördern"}, {"kategorie": "", "text": "Verstößt der Verurteilte gegen die Bedingungen der Bewährungsstrafe oder begeht er während der Bewährungszeit eine neue Straftat, kann das Gericht die Bewährung widerrufen und die ursprünglich verhängte Freiheitsstrafe vollstrecken lassen"}, {"kategorie": "", "text": "Nach erfolgreichem Abschluss der Bewährungszeit und Erfüllung aller Auflagen gilt die Strafe als verbüßt, und der Verurteilte muss die Freiheitsstrafe nicht antreten."}]'::jsonb, ''),
  ('easotzfreiheitsschdrof', 'Easotzfreiheitsschdrof', '', '', '', '', 'Ersatzfreiheitsstrafe', '[{"kategorie": "jur.", "text": "\"strafrechtliche Maßnahme, die in Österreich verhängt wird, wenn eine Geldstrafe nicht bezahlt wird\""}, {"kategorie": "", "text": "Die Ersatzfreiheitsstrafe kommt zum Einsatz, wenn der Verurteilte nicht in der Lage ist, die verhängte Geldstrafe zu zahlen, sei es aufgrund finanzieller Mittel oder durch Verweigerung der Zahlung. Sie wird nur verhängt, wenn alle Versuche, die Geldstrafe einzutreiben, erfolglos waren"}, {"kategorie": "", "text": "Die Dauer der Ersatzfreiheitsstrafe richtet sich nach der Höhe der nicht bezahlten Geldstrafe. Das Gericht legt im Urteil fest, wie viele Tage Freiheitsentzug anstelle der Geldzahlung zu verbüßen sind. Dabei wird eine bestimmte Anzahl an Tagessätzen festgelegt, die in Haft umgewandelt wird (z. B. ein Tag Freiheitsstrafe pro nicht gezahltem [[Tagessatz]])"}, {"kategorie": "", "text": "Die Ersatzfreiheitsstrafe darf nicht länger sein, als es das Gesetz für das zugrunde liegende Delikt vorschreibt. Sie muss verhältnismäßig zur ursprünglichen Geldstrafe stehen"}, {"kategorie": "", "text": "Die Geldstrafe kann auch nach Beginn der Ersatzfreiheitsstrafe noch bezahlt werden. Wenn der Verurteilte die Strafe während des Vollzugs zahlt, wird die Freiheitsstrafe beendet"}, {"kategorie": "", "text": "Die Ersatzfreiheitsstrafe wird wie eine normale Freiheitsstrafe vollstreckt, d. h., der Verurteilte muss sie in einer [[Justizanstalt]] antreten, um die festgelegte Dauer zu verbüßen."}]'::jsonb, ''),
  ('schdrofvoischdreckung', 'Schdrofvoischdreckung', '', '', '', '', 'Strafvollstreckung', '[{"kategorie": "jur.", "text": "\"Vollzug einer gerichtlich verhängten Strafe nach einem rechtskräftigen Urteil im Strafprozess\""}, {"kategorie": "", "text": "Die Strafvollstreckung beginnt, sobald ein Urteil rechtskräftig ist, das heißt, wenn keine weiteren [[Rechtsmittel]] mehr eingelegt werden können oder diese ausgeschöpft sind (siehe [[Rechtskraft]])"}, {"kategorie": "", "text": "Wenn eine Freiheitsstrafe verhängt wurde, erfolgt die Einweisung des Verurteilten in eine [[Justizanstalt]], um die Strafe zu verbüßen"}, {"kategorie": "", "text": "Bei einer Geldstrafe wird der Verurteilte zur Zahlung des festgelegten Betrags verpflichtet. Wenn die Geldstrafe nicht gezahlt wird, kann eine [[Ersatzfreiheitsstrafe]] vollzogen werden"}, {"kategorie": "", "text": "Wenn das Gericht eine bedingte (auf Bewährung ausgesetzte) Strafe verhängt hat, erfolgt die Überwachung der Bewährungsauflagen während der Bewährungszeit"}, {"kategorie": "", "text": "Für die Strafvollstreckung sind die [[Staatsanwaltschaften]] zuständig. Sie überwachen und leiten die Vollstreckung der Strafe ein, indem sie entsprechende Anordnungen erteilen, wie etwa die Vorladung zur Strafverbüßung"}, {"kategorie": "", "text": "Die Strafvollstreckung dient der Durchsetzung der Strafe, die durch das Gericht verhängt wurde, und soll sowohl den Rechtsfrieden wiederherstellen als auch zur Resozialisierung des Verurteilten beitragen."}]'::jsonb, ''),
  ('rechtskroft', 'Rechtskroft', '', '', '', '', 'Rechtskraft', '[{"kategorie": "jur.", "text": "\"Zustand, in dem eine gerichtliche Entscheidung, wie ein [[Urteil]] oder ein [[Beschluss]], endgültig und verbindlich wird, weil keine weiteren [[Rechtsmittel]] (wie [[Berufung]] oder [[Revision]]) mehr zulässig sind oder diese nicht innerhalb der festgelegten Fristen eingelegt wurden\""}, {"kategorie": "", "text": "Ein rechtskräftiges Urteil oder ein rechtskräftiger Beschluss kann nicht mehr angefochten oder geändert werden und ist für alle Beteiligten verbindlich"}, {"kategorie": "", "text": "Die materielle Rechtskraft bedeutet, dass die getroffene Entscheidung für den jeweiligen Rechtsstreit verbindlich ist und nicht erneut über denselben Streitgegenstand vor Gericht verhandelt werden kann. Dies wird als Rechtssicherheit bezeichnet"}, {"kategorie": "", "text": "Eine inhaltlich gleiche Klage oder ein Verfahren mit denselben Streitparteien und demselben Streitgegenstand kann nicht mehr vorgebracht werden (Grundsatz der Rechtskraftwirkung)"}, {"kategorie": "", "text": "Mit der Rechtskraft erlangt das Urteil oder der Beschluss auch vollstreckbare Wirkung. Im Zivilrecht kann der Gläubiger die Ansprüche beispielsweise durch [[Zwangsvollstreckung]] durchsetzen, im Strafrecht folgt die [[Strafvollstreckung]]."}]'::jsonb, ''),
  ('gerichtsuataeu', 'Gerichtsuatäu', '', '', '', '', 'Gerichtsurteil', '[{"kategorie": "jur.", "text": "\"rechtsverbindliche Entscheidung eines [[Gerichts]] im Rahmen eines [[Zivilprozesses]] oder [[Strafprozesses]], durch die der Rechtsstreit bzw. das Strafverfahren endgültig entschieden wird\""}, {"kategorie": "", "text": "Es stellt den Abschluss eines gerichtlichen Verfahrens dar und legt die Rechtsfolgen für die Parteien (im Zivilrecht) oder den Angeklagten (im Strafrecht) fest"}, {"kategorie": "", "text": "Im Zivilprozess entscheidet das Urteil darüber, ob die Ansprüche des Klägers gegen den Beklagten begründet sind, z. B. bei Streitigkeiten über Schadenersatz, Forderungen oder Vertragsverletzungen. Das Urteil kann die Zahlung eines Betrags, die Herausgabe von Eigentum oder die Unterlassung bestimmter Handlungen anordnen. Es beendet den Rechtsstreit und ist für die Parteien verbindlich. Gegen das Urteil können die Parteien [[Rechtsmittel]] einlegen, wie etwa [[Berufung]] oder [[Revision]], um eine Überprüfung durch ein höheres Gericht zu erreichen"}, {"kategorie": "", "text": "Im Strafprozess entscheidet das Urteil, ob der Angeklagte schuldig oder nicht schuldig ist. Im Fall eines Schuldspruchs legt das Gericht auch das Strafmaß fest, z. B. eine Freiheitsstrafe oder Geldstrafe. Das Urteil beendet den Strafprozess und wird nach Verlesung öffentlich verkündet. Bei einem Freispruch wird der Angeklagte von allen Vorwürfen entlastet. Der [[Angeklagte]] oder die [[Staatsanwaltschaft]] kann gegen das Urteil Rechtsmittel wie die [[Berufung]] (gegen das Strafmaß) oder die [[Nichtigkeitsbeschwerde]] (gegen Rechtsfehler) einlegen"}, {"kategorie": "", "text": "Sowohl im Zivil- als auch im Strafprozess ist das Urteil rechtsverbindlich und muss von den Parteien bzw. dem Angeklagten befolgt werden. Sobald das Urteil rechtskräftig ist (wenn keine [[Rechtsmittel]] mehr möglich sind oder eingelegt werden), kann es zwangsweise durchgesetzt werden, z. B. durch [[Zwangsvollstreckung]] im Zivilrecht oder durch [[Strafvollstreckung]] im Strafrecht."}]'::jsonb, ''),
  ('uataeu', 'Uatäu', '', '', '', '', 'Urteil', '[{"kategorie": "jur.", "text": "\"rechtsverbindliche Entscheidung eines [[Gerichts]] im Rahmen eines [[Zivilprozesses]] oder [[Strafprozesses]], durch die der Rechtsstreit bzw. das Strafverfahren endgültig entschieden wird\""}, {"kategorie": "", "text": "Es stellt den Abschluss eines gerichtlichen Verfahrens dar und legt die Rechtsfolgen für die Parteien (im Zivilrecht) oder den Angeklagten (im Strafrecht) fest"}, {"kategorie": "", "text": "Im Zivilprozess entscheidet das Urteil darüber, ob die Ansprüche des Klägers gegen den Beklagten begründet sind, z. B. bei Streitigkeiten über Schadenersatz, Forderungen oder Vertragsverletzungen. Das Urteil kann die Zahlung eines Betrags, die Herausgabe von Eigentum oder die Unterlassung bestimmter Handlungen anordnen. Es beendet den Rechtsstreit und ist für die Parteien verbindlich. Gegen das Urteil können die Parteien [[Rechtsmittel]] einlegen, wie etwa [[Berufung]] oder [[Revision]], um eine Überprüfung durch ein höheres Gericht zu erreichen"}, {"kategorie": "", "text": "Im Strafprozess entscheidet das Urteil, ob der Angeklagte schuldig oder nicht schuldig ist. Im Fall eines Schuldspruchs legt das Gericht auch das Strafmaß fest, z. B. eine Freiheitsstrafe oder Geldstrafe. Das Urteil beendet den Strafprozess und wird nach Verlesung öffentlich verkündet. Bei einem Freispruch wird der Angeklagte von allen Vorwürfen entlastet. Der [[Angeklagte]] oder die [[Staatsanwaltschaft]] kann gegen das Urteil Rechtsmittel wie die [[Berufung]] (gegen das Strafmaß) oder die [[Nichtigkeitsbeschwerde]] (gegen Rechtsfehler) einlegen"}, {"kategorie": "", "text": "Sowohl im Zivil- als auch im Strafprozess ist das Urteil rechtsverbindlich und muss von den Parteien bzw. dem Angeklagten befolgt werden. Sobald das Urteil rechtskräftig ist (wenn keine [[Rechtsmittel]] mehr möglich sind oder eingelegt werden), kann es zwangsweise durchgesetzt werden, z. B. durch [[Zwangsvollstreckung]] im Zivilrecht oder durch [[Strafvollstreckung]] im Strafrecht."}]'::jsonb, ''),
  ('vagleich', 'Vagleich', '', '', '', '', 'Vergleich', '[{"kategorie": "jur.", "text": "\"einvernehmliche Vereinbarung zwischen den streitenden Parteien, die während eines [[Gerichtsverfahrens]] getroffen wird und vom [[Gericht]] als rechtsverbindliche Entscheidung anerkannt wird\""}, {"kategorie": "", "text": "Durch diesen Vergleich wird der Rechtsstreit außergerichtlich beigelegt, ohne dass es zu einem [[Urteil]] kommt"}, {"kategorie": "", "text": "Der gerichtliche Vergleich basiert auf der freiwilligen Einigung beider Parteien über den Streitgegenstand, oft unter Mitwirkung des Gerichts. Er kann während der Verhandlung oder im Vorfeld eines Urteils zustande kommen"}, {"kategorie": "", "text": "Der Vergleich wird im Protokoll festgehalten und ist rechtlich bindend. Er hat die gleiche Wirkung wie ein Gerichtsurteil und ist sofort vollstreckbar, wenn eine Partei die vereinbarten Bedingungen nicht einhält"}, {"kategorie": "", "text": "Mit dem Abschluss des Vergleichs ist das gerichtliche Verfahren beendet. Es gibt keine Notwendigkeit für eine weitere gerichtliche Entscheidung oder ein Urteil"}, {"kategorie": "", "text": "Der gerichtliche Vergleich ermöglicht eine schnelle und kostengünstige Lösung des Konflikts, vermeidet die Unsicherheiten eines Urteils und ermöglicht den Parteien, sich auf einen Kompromiss zu einigen, der für beide akzeptabel ist."}]'::jsonb, ''),
  ('zwaungsvaschdeigarung', 'Zwaungsvaschdeigarung', '', '', '', '', 'Zwangsversteigerung', '[{"kategorie": "jur.", "text": "\"Form der [[Zwangsvollstreckung]], bei der das Eigentum eines Schuldners, insbesondere Immobilien oder bewegliche Sachen, öffentlich versteigert wird, um die Forderungen eines Gläubigers zu befriedigen\""}, {"kategorie": "", "text": "Sie wird angeordnet, wenn der Schuldner seine Schulden nicht freiwillig zahlt und andere Zwangsvollstreckungsmaßnahmen nicht ausreichen"}, {"kategorie": "", "text": "Die Zwangsversteigerung wird vom [[Exekutionsgericht]] auf Antrag des Gläubigers angeordnet. Das Gericht legt fest, welche Vermögensgegenstände versteigert werden, und überwacht das Verfahren"}, {"kategorie": "", "text": "Bei Immobilien erfolgt die Versteigerung durch einen gerichtlichen Versteigerungstermin, bei dem die Immobilie öffentlich angeboten wird. Der Erlös aus dem Verkauf wird zur Befriedigung der Gläubiger verwendet"}, {"kategorie": "", "text": "Häufig sind Immobilien (z. B. Häuser oder Wohnungen) Gegenstand einer Zwangsversteigerung, aber auch bewegliche Sachen wie Autos oder wertvolle Gegenstände können versteigert werden"}, {"kategorie": "", "text": "Vor der Zwangsversteigerung sind verschiedene Schutzmaßnahmen vorgesehen, z. B. die Möglichkeit des Schuldners, durch Zahlung die Versteigerung abzuwenden, oder die Festlegung eines Mindestgebots, um den Wert des Vermögens zu sichern"}, {"kategorie": "", "text": "Der durch die Versteigerung erzielte Erlös wird nach einem festgelegten Verfahren an die Gläubiger verteilt. Wenn der Erlös nicht ausreicht, um alle Forderungen zu decken, verbleibt der Restbetrag als ungedeckte Schulden"}, {"kategorie": "", "text": "Die Zwangsversteigerung ist ein letztes Mittel, um die Schulden des Schuldners durch den Verkauf seines Eigentums zu begleichen. Sie wird streng nach den gerichtlichen Vorgaben durchgeführt, um sowohl die Rechte der Gläubiger als auch den Schutz des Schuldners zu gewährleisten."}]'::jsonb, ''),
  ('zwaungsvoischdreckung', 'Zwaungsvoischdreckung', '', '', '', '', 'Zwangsvollstreckung', '[{"kategorie": "jur.", "text": "\"gerichtliches Verfahren, mit dem ein Gläubiger seine durch ein Gerichtsurteil oder einen anderen [[vollstreckbaren]] Titel festgestellten Ansprüche gegen den Schuldner durchsetzen kann, wenn dieser nicht freiwillig leistet\""}, {"kategorie": "", "text": "Sie ermöglicht dem Gläubiger, die Zahlung von Schulden oder die Erfüllung von anderen Verpflichtungen durch Zwangsmaßnahmen zu erzwingen"}, {"kategorie": "", "text": "Voraussetzung für die Zwangsvollstreckung ist ein [[vollstreckbarer]] Titel (wie ein [[Gerichtsurteil]], ein [[gerichtlicher]] Vergleich oder ein notarieller Schuldschein, der die Forderung des Gläubigers bestätigt)"}, {"kategorie": "", "text": "Die Zwangsvollstreckung wird vom [[Exekutionsgericht]] angeordnet und durchgeführt. Das Gericht entscheidet, welche Maßnahmen ergriffen werden, und überwacht deren Vollzug"}, {"kategorie": "", "text": "Zu den möglichen Maßnahmen gehören die Pfändung von Konten, Löhnen oder beweglichen Sachen, die [[Zwangsversteigerung]] von Immobilien oder beweglichen Gegenständen sowie die Räumung von Wohnungen"}, {"kategorie": "", "text": "Das Verfahren sieht auch bestimmte Schutzmechanismen für den Schuldner vor, wie etwa Pfändungsfreigrenzen bei Gehaltspfändungen, um das Existenzminimum zu sichern."}]'::jsonb, ''),
  ('exekutionsgricht', 'Exekutionsgricht', '', '', '', '', 'Exekutionsgericht', '[{"kategorie": "jur.", "text": "\"zuständiges Gericht für die Durchführung eines [[Exekutionsverfahrens]], also der [[Zwangsvollstreckung]] von Forderungen, die durch ein Gerichtsurteil oder einen anderen [[vollstreckbaren]] Titel festgestellt wurden\""}, {"kategorie": "", "text": "Das Exekutionsgericht entscheidet über Anträge auf [[Zwangsvollstreckung]] und ordnet Maßnahmen wie Pfändungen, Zwangsversteigerungen oder Lohnexekutionen an. Es ist auch für einstweilige Sicherungsmaßnahmen zuständig"}, {"kategorie": "", "text": "Das Exekutionsgericht prüft, ob die Voraussetzungen für die Zwangsvollstreckung vorliegen, und erlässt entsprechende [[Beschlüsse]] oder [[Verfügungen]]"}, {"kategorie": "", "text": "Zuständig ist in der Regel das [[Bezirksgericht]] am Wohnsitz des Schuldners oder dort, wo die Vollstreckung durchgeführt werden soll"}, {"kategorie": "", "text": "Das Exekutionsgericht beaufsichtigt den gesamten Vollstreckungsprozess und sorgt dafür, dass die Maßnahmen korrekt und im Rahmen des Gesetzes durchgeführt werden"}, {"kategorie": "", "text": "Das Exekutionsgericht spielt somit eine zentrale Rolle bei der gerichtlichen Durchsetzung von Ansprüchen und der Anwendung von Zwangsmaßnahmen im Exekutionsverfahren."}]'::jsonb, ''),
  ('exekutionsvafoan', 'Exekutionsvafoan', '', '', '', '', 'Exekutionsverfahren', '[{"kategorie": "jur.", "text": "\"gerichtliches Verfahren zur Durchsetzung von Geldforderungen oder anderen Ansprüchen, die durch ein gerichtliches Urteil, einen gerichtlichen Beschluss oder einen anderen vollstreckbaren [[Titel]] festgestellt wurden\""}, {"kategorie": "", "text": "Es dient dazu, Gläubigern zu ermöglichen, ihre Forderungen zwangsweise gegenüber dem Schuldner geltend zu machen, wenn dieser nicht freiwillig zahlt"}, {"kategorie": "", "text": "Merkmale des Exekutionsverfahrens:  (i) [[Zwangsvollstreckung]] (das Verfahren erlaubt Maßnahmen wie Gehaltspfändung, Kontopfändung, Sachpfändung oder Zwangsversteigerung von Eigentum des Schuldners),  (ii) Vollstreckbarer Titel (Voraussetzung für das Exekutionsverfahren ist ein vollstreckbarer Titel, z. B. ein Gerichtsurteil oder ein notariell beglaubigter Schuldschein),  (iii) Beantragung (der Gläubiger muss das Verfahren beim zuständigen [[Exekutionsgericht]] beantragen"}, {"kategorie": "", "text": "Ziel des Exekutionsverfahrens ist es, die Ansprüche des Gläubigers durch Zwangsmaßnahmen zu erfüllen, wenn der Schuldner seinen Verpflichtungen nicht nachkommt. Das Verfahren bietet somit eine Möglichkeit, rechtskräftig festgestellte Ansprüche durchzusetzen."}]'::jsonb, ''),
  ('aussaschdreitvafoan', 'Außaschdreitvafoan', '', '', '', '', 'Außerstreitverfahren', '[{"kategorie": "jur.", "text": "\"besonderes gerichtliches Verfahren, das für Angelegenheiten vorgesehen ist, bei denen keine streitige Auseinandersetzung zwischen den Parteien im Vordergrund steht\""}, {"kategorie": "", "text": "Es dient der Regelung, Gestaltung oder Genehmigung von Rechtsverhältnissen, ohne dass ein typischer Rechtsstreit zwischen [[Kläger]] und [[Beklagtem]] ausgetragen wird"}, {"kategorie": "", "text": "Typische Bereiche sind das Familienrecht (z. B. Obsorge, Unterhalt), das Erbrecht (z. B. Verlassenschaftsabhandlungen), Grundbuchangelegenheiten oder Pflegschaftsverfahren"}, {"kategorie": "", "text": "Im Gegensatz zu Streitverfahren stehen keine gegensätzlichen Positionen im Vordergrund, sondern die Gestaltung oder Genehmigung eines Rechtsverhältnisses, oft im Interesse Dritter (z.B. von Kindern oder Erben)"}, {"kategorie": "", "text": "Das Gericht handelt oft von Amts wegen und hat eine aktive Rolle. Es ermittelt den Sachverhalt selbst und entscheidet, wie die Angelegenheit zu regeln ist"}, {"kategorie": "", "text": "Das Außerstreitverfahren ist in der Regel weniger formal und flexibler als ein streitiges Zivilverfahren. Es dient der schnellen und effektiven Regelung von Angelegenheiten, ohne unnötigen Aufwand."}]'::jsonb, ''),
  ('vafuegung', 'Vafügung', '', '', '', '', 'Verfügung', '[{"kategorie": "jur.", "text": "\"rechtsverbindliche Anordnung einer Behörde oder eines Gerichts, die bestimmte Rechtsfolgen herbeiführt oder Verfahrensabläufe regelt\""}, {"kategorie": "", "text": "Sie wird sowohl im [[Verwaltungsrecht]] als auch in [[Gerichtsverfahren]] eingesetzt"}, {"kategorie": "", "text": "[[Verwaltungsrecht]]: Verfügungen regeln Rechtsverhältnisse wie Genehmigungen, Untersagungen oder Anordnungen (z. B. Baugenehmigungen oder Sicherheitsauflagen). Sie werden von Verwaltungsbehörden erlassen und betreffen die Rechte oder Pflichten von Einzelpersonen oder Institutionen"}, {"kategorie": "", "text": "[[Gerichtsverfahren]]:\nIm [[Zivil-]] oder [[Strafverfahren]] ergehen Verfügungen, um verfahrensleitende Maßnahmen zu treffen, z. B. Ladungen, Beweisanordnungen oder Sicherstellungsanordnungen"}, {"kategorie": "", "text": "Vorläufige oder endgültige Regelungen: Eine vorläufige Verfügung trifft vorläufige Maßnahmen, wie z. B. eine [[einstweilige]] Verfügung, bis eine endgültige Entscheidung gefällt wird. Endgültige Verfügungen sind abschließende Entscheidungen über bestimmte Anträge oder Sachverhalte"}, {"kategorie": "", "text": "Gegen Verfügungen kann [[Rechtsmittel]] eingelegt werden, z. B. durch [[Rekurs]] oder [[Beschwerde]], um die Entscheidung durch ein höheres Gericht oder eine Behörde überprüfen zu lassen"}, {"kategorie": "", "text": "Verfügungen sind oft sofort vollziehbar, können jedoch angefochten werden, um ihre Rechtmäßigkeit zu überprüfen."}]'::jsonb, ''),
  ('beschluss', 'Beschluss', '', '', '', '', 'Beschluss', '[{"kategorie": "jur.", "text": "\"gerichtliche Entscheidung, die im Rahmen eines Verfahrens ergeht, jedoch in der Regel kein Endurteil darstellt\""}, {"kategorie": "", "text": "Beschlüsse werden für Entscheidungen verwendet, die Verfahrensfragen regeln oder in bestimmten Verfahrensarten die Hauptentscheidung darstellen"}, {"kategorie": "", "text": "Sie können sowohl in [[Zivil-]] als auch in [[Straf-]] und [[Verwaltungsverfahren]] erlassen werden und betreffen typischerweise Zwischenentscheidungen, verfahrensleitende Maßnahmen oder Entscheidungen in außerstreitigen oder Exekutionsverfahren"}, {"kategorie": "", "text": "Ein Beschluss wird oft verwendet, um Verfahrensfragen zu klären, die während eines Prozesses auftreten. Beispiele sind: (i) Bewilligung von Beweisanträgen, (ii) Zurückweisung von Schriftsätzen, (iii) Anordnung von Beweisaufnahmen, (iv) Ablehnung eines Antrags auf Verfahrenshilfe"}, {"kategorie": "", "text": "In bestimmten Verfahrensarten, wie etwa im [[Außerstreitverfahren]] oder im [[Exekutionsverfahren]], wird die Hauptentscheidung des Gerichts als Beschluss und nicht als Urteil erlassen. Beispielsweise: (i) Bewilligung einer Pfändung oder Zwangsversteigerung, (ii) Anordnung eines Sachverständigengutachtens, (iii) Anordnung einer einstweiligen Verfügung. In diesen Verfahren erfüllt der Beschluss die Funktion eines Endurteils"}, {"kategorie": "", "text": "Im [[Zivilprozess]] ergehen Beschlüsse häufig zur Verfahrensführung, wie etwa die Vertagung eines Verhandlungstermins, die Zurückweisung einer Klage wegen formeller Mängel oder die Entscheidung über Verfahrenskosten"}, {"kategorie": "", "text": "Im [[Strafprozess]] gibt es Beschlüsse beispielsweise bei der Anordnung von Untersuchungshaft, der Hausdurchsuchung oder der Beschlagnahme von Beweismitteln"}, {"kategorie": "", "text": "Gegen einen Beschluss kann in der Regel der [[Rekurs]] eingelegt werden, der das zuständige höhere Gericht mit der Überprüfung der Entscheidung befasst."}]'::jsonb, ''),
  ('widaschbruch', 'Widaschbruch', '', '', '', '', 'Widerspruch', '[{"kategorie": "jur.", "text": "\"Rechtsmittel, das es einer betroffenen Person ermöglicht, gegen eine behördliche oder gerichtliche Entscheidung Einspruch zu erheben, um deren Überprüfung und gegebenenfalls Änderung zu verlangen\""}, {"kategorie": "", "text": "Der Widerspruch wird oft im [[Verwaltungsrecht]] verwendet, um gegen Verwaltungsakte vorzugehen (z. B. [[Bescheide]], Genehmigungen, Abgabenbescheide), aber auch in anderen Rechtsbereichen, etwa im [[Zivilprozess]], um sich gegen eine [[einstweilige]] Verfügung oder Mahnungen zu wehren."}]'::jsonb, ''),
  ('rekuas', 'Rekuas', '', '', '', '', 'Rekurs', '[{"kategorie": "jur.", "text": "\"Rechtsmittel im österreichischen [[Zivilrecht]], mit dem eine gerichtliche Entscheidung in Form eines [[Beschlusses]] angefochten werden kann\""}, {"kategorie": "", "text": "Er richtet sich nicht gegen Urteile, sondern gegen [[Beschlüsse]] oder [[Verfügungen]] eines Gerichts, die während des Verfahrens oder in Zwangsvollstreckungsverfahren erlassen werden"}, {"kategorie": "", "text": "Der Rekurs ermöglicht es den Parteien, die Überprüfung dieser Entscheidungen durch ein höheres Gericht zu verlangen"}, {"kategorie": "", "text": "Gegen Beschlüsse eines [[Bezirksgerichts]] kann Rekurs an das [[Landesgericht]] eingelegt werden. Gegen Beschlüsse eines Landesgerichts als erste Instanz geht der Rekurs an das [[Oberlandesgericht]]"}, {"kategorie": "", "text": "Besonders häufig wird der Rekurs im Exekutionsverfahren verwendet, also bei der [[Zwangsvollstreckung]] von gerichtlichen Entscheidungen, wie etwa der Anordnung einer Pfändung, Zwangsversteigerung oder Räumung. Hier können Schuldner oder Gläubiger durch Rekurs gegen Beschlüsse vorgehen, die im Rahmen der Vollstreckung erlassen wurden, um deren Rechtmäßigkeit überprüfen zu lassen"}, {"kategorie": "", "text": "Das Rekursgericht (die nächsthöhere Instanz) entscheidet über den Rekurs in der Regel ohne mündliche Verhandlung, basierend auf den Schriftsätzen und Akten. Es kann die Entscheidung des erstinstanzlichen Gerichts entweder bestätigen, abändern oder zurückverweisen, wenn eine Neuverhandlung erforderlich ist."}]'::jsonb, ''),
  ('beschweade', 'Beschweade', '', '', '', '', 'Beschwerde', '[{"kategorie": "jur.", "text": "\"[[Rechtsmittel]] im österreichischen Rechtssystem, das es einer betroffenen Person ermöglicht, gegen Entscheidungen von [[Gerichten]] oder [[Verwaltungsbehörden]] vorzugehen\""}, {"kategorie": "", "text": "Sie dient der Überprüfung einer Entscheidung durch ein höheres Gericht oder eine andere Instanz und kann sich sowohl auf rechtliche als auch auf tatsächliche Fehler beziehen"}, {"kategorie": "", "text": "Die Beschwerde ist ein wesentliches Instrument, um Verfahrensfehler, rechtswidrige Entscheidungen oder Verwaltungsakte anzufechten"}, {"kategorie": "", "text": "Die Beschwerde kann in verschiedenen Rechtsbereichen eingesetzt werden, insbesondere im [[Verwaltungsrecht]], aber auch in [[Zivilverfahren]] und [[Strafsachen]]"}, {"kategorie": "", "text": "Im Verwaltungsrecht ist die Beschwerde ein zentraler Rechtsbehelf gegen Verwaltungsakte (Entscheidungen von Behörden wie [[Bescheide]], etc.). Hier können Personen, die sich durch eine behördliche Entscheidung in ihren Rechten verletzt sehen, eine Beschwerde bei einem [[Verwaltungsgericht]] einlegen. Verwaltungsgerichte überprüfen die Entscheidung der Behörde sowohl in rechtlicher als auch in sachlicher Hinsicht. Nach der Entscheidung des Verwaltungsgerichts kann eine weitere Beschwerde beim [[Verwaltungsgerichtshof]] (VwGH) oder beim [[Verfassungsgerichtshof]] (VfGH) erhoben werden, wenn es sich um eine Frage der Rechtsanwendung oder um eine mögliche Verletzung von [[Grundrechten]] handelt"}, {"kategorie": "", "text": "In [[Zivilverfahren]] kann die Beschwerde gegen verfahrensleitende Beschlüsse oder Zwischenentscheidungen eines Gerichts eingelegt werden, etwa bei der Ablehnung von Beweisanträgen oder der Entscheidung über Verfahrenskosten. Die Beschwerde im Zivilrecht wird in der Regel an das zuständige Berufungsgericht oder ein Obergericht gerichtet, das die Entscheidung überprüft und entweder bestätigt, aufhebt oder abändert"}, {"kategorie": "", "text": "Im [[Strafrecht]] kann eine Beschwerde gegen verfahrensleitende Entscheidungen eingelegt werden, beispielsweise wenn es um Haftanordnungen, Beschlagnahmen oder andere Maßnahmen geht, die den Verfahrensfortgang betreffen.\nDiese Beschwerde wird von einem höheren Gericht geprüft, das entscheidet, ob die Maßnahme rechtmäßig und verhältnismäßig ist."}]'::jsonb, ''),
  ('revision', 'Revision', '', '', '', '', 'Revision', '[{"kategorie": "jur.", "text": "[[Rechtsmittel im österreichischen Recht, das es ermöglicht, eine gerichtliche Entscheidung von einem höheren [[Gericht]] auf Rechtsfehler überprüfen zu lassen]]"}, {"kategorie": "", "text": "Anders als die [[Berufung]] zielt die Revision ausschließlich auf die rechtliche Prüfung des Urteils ab und nicht auf die Tatsachenfeststellung oder Beweiswürdigung"}, {"kategorie": "", "text": "Die Revision kann in [[Zivilverfahren]], [[Strafverfahren]] und [[Verwaltungsverfahren]] eingebracht werden, wobei jeweils bestimmte Voraussetzungen erfüllt sein müssen"}, {"kategorie": "", "text": "Eine Revision kann nur gegen Urteile höherer Instanzen eingelegt werden, meist gegen Urteile von [[Landesgerichten]] oder [[Oberlandesgerichten]]"}, {"kategorie": "", "text": "In Zivilverfahren ist die Revision nur zulässig, wenn der Fall eine grundsätzliche Rechtsfrage betrifft, die über den Einzelfall hinaus von Bedeutung ist. Oft ist es erforderlich, dass das Urteil Rechtsfragen von erheblicher Bedeutung für die Einheitlichkeit der [[Rechtsprechung]] betrifft"}, {"kategorie": "", "text": "In Strafsachen kann eine Revision wegen schwerwiegender Rechtsfehler (wie falscher Rechtsanwendung oder Verfahrensmängeln) eingereicht werden. Die Revision im Strafrecht wird vor dem [[Obersten]] Gerichtshof (OGH) verhandelt"}, {"kategorie": "", "text": "Das Revisionsgericht ist in der Regel ein höheres Gericht: (i) In Zivilverfahren ist der Oberste Gerichtshof (OGH) für Revisionen zuständig,  (ii) Im Strafrecht wird die Revision ebenfalls vor dem OGH verhandelt,  (iii) Im Verwaltungsrecht kann die Revision zum [[Verwaltungsgerichtshof]] (VwGH) eingereicht werden, sofern es um die Überprüfung von Rechtsfragen im [[Verwaltungsverfahren]] geht"}, {"kategorie": "", "text": "Das Revisionsgericht kann das angefochtene Urteil entweder (i) bestätigen (wenn es keine Rechtsfehler findet), oder (ii) aufheben und zur Neuverhandlung an das untergeordnete Gericht zurückverweisen, oder (iii) das Urteil abändern, falls der Rechtsfehler eindeutig ist."}]'::jsonb, ''),
  ('berufung', 'Berufung', '', '', '', '', 'Berufung', '[{"kategorie": "jur.", "text": "\"Rechtsmittel im österreichischen Recht, das es einer Partei ermöglicht, eine gerichtliche Entscheidung der ersten Instanz anzufechten und von einem höheren Gericht überprüfen zu lassen\""}, {"kategorie": "", "text": "Die Berufung dient dazu, sowohl rechtliche Fehler als auch Tatsachenfehler im Urteil zu korrigieren. Sie kommt insbesondere im [[Zivilrecht]] und [[Strafrecht]] zur Anwendung und ist ein zentraler Bestandteil des [[Instanzenzugs]] in Österreich"}, {"kategorie": "", "text": "Die Berufung kann gegen Urteile von [[Bezirksgerichten]] oder [[Landesgerichten]] eingelegt werden, die als erste Instanz tätig waren"}, {"kategorie": "", "text": "Im Zivilrecht ermöglicht die Berufung eine vollständige Überprüfung der Entscheidung, sowohl in Bezug auf die rechtliche als auch die tatsächliche Seite (Beweiswürdigung, Sachverhaltsfeststellung)"}, {"kategorie": "", "text": "Im Strafrecht kann eine Berufung entweder gegen den Schuldspruch, das Strafmaß oder beides gerichtet sein. Hier wird das Urteil ebenfalls auf Fehler in der Anwendung des Strafrechts oder auf unzureichende Tatsachenfeststellung überprüft."}]'::jsonb, ''),
  ('instanznzug', 'Instanznzug', '', '', '', '', 'Instanzenzug', '[{"kategorie": "jur.", "text": "\"gerichtlicher Instanzenweg, den ein Rechtsfall durchläuft, wenn gegen eine gerichtliche Entscheidung ein [[Rechtsmittel]] eingelegt wird\""}, {"kategorie": "", "text": "Er bezeichnet die Abfolge von Gerichtsinstanzen, die den Fall nacheinander überprüfen und in höheren Instanzen rechtlich überprüfen und entscheiden können"}, {"kategorie": "", "text": "Der Instanzenzug ist ein grundlegendes Prinzip im österreichischen Rechtssystem und stellt sicher, dass gerichtliche Entscheidungen von einem höheren Gericht überprüft werden können, um Fehler zu korrigieren und die Rechtsstaatlichkeit zu gewährleisten"}, {"kategorie": "", "text": "Das österreichische Gerichtssystem ist mehrstufig aufgebaut, wobei je nach Verfahrensart (Zivil-, Straf-, oder Verwaltungsrecht) unterschiedliche Gerichtswege bestehen"}, {"kategorie": "", "text": "Im Zivilrecht beginnt ein Verfahren oft vor einem [[Bezirksgericht]] oder [[Landesgericht]] (je nach Streitwert). Gegen die Entscheidung kann [[Berufung]] oder [[Revision]] eingelegt werden. Der [[Instanzenzug]] verläuft hier über das [[Oberlandesgericht]] (OLG) und letztlich zum [[Obersten]] Gerichtshof (OGH), der als letzte Instanz über Rechtsfragen entscheidet"}, {"kategorie": "", "text": "m Strafrecht wird ein Verfahren entweder vor einem Bezirksgericht (für minder schwere Delikte) oder einem Landesgericht (für schwerere Straftaten) verhandelt. Gegen Urteile in Strafsachen können Rechtsmittel wie [[Berufung]] (gegen das Strafmaß) oder [[Nichtigkeitsbeschwerde]] (gegen Rechtsfehler) eingelegt werden, die beim Oberlandesgericht oder beim Obersten Gerichtshof überprüft werden"}, {"kategorie": "", "text": "Im Verwaltungsrecht können Entscheidungen von [[Verwaltungsbehörden]] vor den [[Verwaltungsgerichten]] angefochten werden. Diese Gerichte überprüfen die Entscheidungen der Verwaltung und haben als nächste Instanz den [[Verwaltungsgerichtshof]] (VwGH), der Rechtsfragen prüft. Zusätzlich kann auch der [[Verfassungsgerichtshof]] (VfGH) angerufen werden, wenn Grundrechte oder verfassungsrechtliche Fragen betroffen sind."}]'::jsonb, ''),
  ('europawoi', 'Europawoi', '', '', '', '', 'Europawahl', '[{"kategorie": "pol.", "text": "\"Wahl zum Europäischen Parlament, bei der Bürger der Europäischen Union (EU) alle fünf Jahre ihre Vertreter auf europäischer Ebene wählen\""}, {"kategorie": "", "text": "Sie ermöglicht den Bürgern der EU-Mitgliedstaaten, direkt an der [[politischen]] Willensbildung der Europäischen Union teilzunehmen und die Abgeordneten zu wählen, die ihre Interessen im Europäischen Parlament vertreten. In Österreich findet die Europawahl im Rahmen der allgemeinen Wahlrechte statt, und sie ist eine der wichtigsten Wahlen auf supranationaler Ebene"}, {"kategorie": "", "text": "Alle österreichischen [[Staatsbürger]] ab 16 Jahren sowie alle EU-Bürger, die ihren Hauptwohnsitz in Österreich haben, dürfen an der Europawahl teilnehmen"}, {"kategorie": "", "text": "Die Europawahl in Österreich erfolgt nach dem Verhältniswahlrecht, bei dem die Anzahl der Sitze, die eine Partei im Europäischen Parlament erhält, proportional zu ihrem Stimmenanteil ist"}, {"kategorie": "", "text": "Österreich bildet für die Europawahl einen einzigen Wahlkreis. Das Land hat derzeit 19 Sitze im Europäischen Parlament, die entsprechend dem Ergebnis der Europawahl auf die Parteien verteilt werden"}, {"kategorie": "", "text": "Die genaue Anzahl der Sitze, die jedem Mitgliedstaat zusteht, richtet sich nach der Bevölkerungsgröße des Landes. Österreich gehört zu den mittelgroßen Mitgliedstaaten"}, {"kategorie": "", "text": "Die österreichischen Parteien, die bei der Europawahl antreten, sind in der Regel Mitglieder größerer europäischer Parteienfamilien, wie z.B. der Europäischen Volkspartei (EVP) oder der Progressiven Allianz der Sozialisten und Demokraten (S&D)"}, {"kategorie": "", "text": "Die Europawahl ist die wichtigste Möglichkeit für Bürger der Europäischen Union, auf die politische Gestaltung der EU Einfluss zu nehmen. Sie findet alle fünf Jahre statt und bestimmt die Zusammensetzung des Europäischen Parlaments, das eine zentrale Rolle in der Gesetzgebung und Überwachung der EU-Institutionen spielt und über eine Vielzahl von Bereichen entscheidet, die das tägliche Leben der EU-Bürger betreffen, wie z. B. Handelsabkommen, Klimaschutz, Verbraucherrechte und den Binnenmarkt."}]'::jsonb, ''),
  ('rechtsmittl', 'Rechtsmittl', '', '', '', '', 'Rechtsmittel', '[{"kategorie": "jur.", "text": "\"juristische Instrumente, die es einer Partei in einem Gerichtsverfahren ermöglichen, eine gerichtliche Entscheidung anzufechten und eine Überprüfung dieser Entscheidung durch ein höheres [[Gericht]] zu verlangen\""}, {"kategorie": "", "text": "Das Ziel von Rechtsmitteln ist es, mögliche Fehler oder Unzulänglichkeiten in der Rechtsanwendung oder in der Feststellung von Tatsachen in einem erstinstanzlichen Urteil zu korrigieren"}, {"kategorie": "", "text": "In Österreich gibt es verschiedene Arten von Rechtsmitteln, die je nach Verfahrensart (Zivil-, Straf- oder Verwaltungsrecht) eingesetzt werden können:  (i) Berufung (ein Rechtsmittel gegen ein erstinstanzliches Urteil in Zivil- oder Strafsachen. Hier wird die Sache und gegebenenfalls auch die Tatsachenfeststellung überprüft),  (ii) Revision (ein Rechtsmittel, das sich vor allem auf die Überprüfung der Rechtsanwendung in der Entscheidung konzentriert. Es wird in Zivilsachen oder Verwaltungsverfahren beim [[Obersten]] Gerichtshof oder [[Verwaltungsgerichtshof]] eingelegt),  (iii) Nichtigkeitsbeschwerde (ein spezielles Rechtsmittel im Strafrecht, das zur Überprüfung von Rechtsfehlern dient. Es kann gegen Urteile der [[Strafgerichte]] eingebracht werden, wenn schwerwiegende Fehler im Verfahren oder bei der Rechtsanwendung vorliegen),  (iv) Beschwerde (ein Rechtsmittel, das in bestimmten Verfahren (vor allem im Verwaltungsrecht) gegen Entscheidungen einer Behörde oder eines Gerichts eingelegt werden kann)"}, {"kategorie": "", "text": "Rechtsmittel in Österreich führen in der Regel dazu, dass das Verfahren vor ein höheres Gericht gelangt ([[Instanzenzug]]). Je nach Instanzgericht wird der Fall dann vor einem [[Landesgericht]], [[Oberlandesgericht]], dem [[Obersten]] Gerichtshof (OGH), [[Verwaltungsgerichtshof]] (VwGH) oder [[Verfassungsgerichtshof]] (VfGH) verhandelt."}]'::jsonb, ''),
  ('woirecht', 'Woirecht', '', '', '', '', 'Wahlrecht', '[{"kategorie": "pol.", "text": "\"grundlegendes demokratisches Recht, das den [[Bürgern]] ermöglicht, durch Wahlen an der [[politischen]] Willensbildung teilzunehmen\""}, {"kategorie": "", "text": "Es umfasst das aktive und passive Wahlrecht, d.h. das Recht zu wählen und das Recht, gewählt zu werden"}, {"kategorie": "", "text": "Das Wahlrecht spielt eine zentrale Rolle in der [[repräsentativen]] Demokratie Österreichs, da es sicherstellt, dass die Bevölkerung regelmäßig ihre politischen Vertreter bestimmt"}, {"kategorie": "", "text": "In Österreich dürfen alle [[Staatsbürger]] ab 16 Jahren bei [[Nationalratswahlen]], [[Landtagswahlen]], [[Gemeinderatswahlen]] und der Wahl des [[Bundespräsidenten]] wählen"}, {"kategorie": "", "text": "Das Wahlrecht gilt auch für EU-Bürger bei Gemeinderatswahlen und [[Europawahlen]], sofern sie in Österreich ihren Hauptwohnsitz haben"}, {"kategorie": "", "text": "Die Wahlen sind frei, gleich, geheim und unmittelbar, was bedeutet, dass jeder Wähler seine Stimme ohne Druck oder Zwang abgeben kann, jede Stimme den gleichen Wert hat und die Stimmabgabe anonym erfolgt"}, {"kategorie": "", "text": "Kandidiert man für das Amt des Bundespräsidenten, muss man mindestens 35 Jahre alt sein. Für die Kandidatur bei anderen Wahlen gelten in der Regel die gleichen Voraussetzungen wie beim aktiven Wahlrecht (Mindestalter von 18 Jahren für den Nationalrat)"}, {"kategorie": "", "text": "In Österreich gibt es mehrere Wahlarten, bei denen das Wahlrecht ausgeübt wird:  (i) Nationalratswahl (Wahlen zum [[Nationalrat]], dem österreichischen [[Parlament]], finden alle fünf Jahre statt. Der Nationalrat ist das zentrale Organ der [[Gesetzgebung]] auf Bundesebene),  (ii) Landtagswahlen (in den neun [[Bundesländern]] wählen die Bürger die [[Landtage]], die für die Gesetzgebung auf Landesebene zuständig sind,  (iii) Gemeinderatswahlen (in den Gemeinden wählen die Bürger die Mitglieder der [[Gemeinderäte]], die die lokale Verwaltung leiten),  (iv) Präsidentschaftswahl (der Bundespräsident wird direkt vom Volk gewählt, die Amtszeit beträgt sechs Jahre, und eine Wiederwahl ist nur einmal möglich), (v) Europawahl: Alle fünf Jahre wählen österreichische Bürger und EU-Bürger, die in Österreich leben, die Abgeordneten zum Europäischen Parlament"}, {"kategorie": "", "text": "In Österreich besteht keine Wahlpflicht. Das bedeutet, dass die Teilnahme an Wahlen freiwillig ist, es gibt jedoch regelmäßige Kampagnen zur Förderung der Wahlbeteiligung"}, {"kategorie": "", "text": "Bestimmte Personengruppen, wie etwa verurteilte Straftäter, können das Wahlrecht durch gerichtliche Entscheidung vorübergehend oder dauerhaft verlieren. In der Praxis ist dies jedoch selten, und solche Einschränkungen unterliegen strengen rechtlichen Vorgaben."}]'::jsonb, ''),
  ('generalprokuratur', 'Generalprokuratur', '', '', '', '', 'Generalprokuratur', '[{"kategorie": "allg.", "text": "\"oberste Behörde der Strafrechtspflege in Österreich, die den [[Obersten]] Gerichtshof (OGH) in Rechtsfragen berät, jedoch nicht selbst Anklagen erhebt oder [[Strafverfahren]] leitet\""}, {"kategorie": "", "text": "Sie fungiert als unabhängiges Organ und hat die Aufgabe, die ordnungsgemäße Anwendung des Rechts sicherzustellen. Ihre Hauptaufgabe besteht darin, das Recht zu schützen, indem sie auf Rechtsfehler in Urteilen hinweist und den OGH unterstützt, ohne direkt Partei in einem Verfahren zu sein"}, {"kategorie": "", "text": "Die Generalprokuratur dient als rechtliches Kontrollorgan und ist beim Obersten Gerichtshof (OGH) angesiedelt. Sie nimmt an Verfahren vor dem OGH teil, wenn es um Rechtsmittel oder Revisionen geht, jedoch nur als Amicus Curiae (Freund des Gerichts), nicht als Partei. Sie gibt Stellungnahmen zu wichtigen Rechtsfragen ab und kann in Fällen, in denen sie einen Rechtsfehler erkennt, die Wiederaufnahme eines Verfahrens beantragen"}, {"kategorie": "", "text": "Die Generalprokuratur ist direkt dem Bundesministerium für Justiz unterstellt, arbeitet jedoch unabhängig und ohne Weisungen"}, {"kategorie": "", "text": "Sie steht organisatorisch auf einer Ebene mit der [[Oberstaatsanwaltschaft]], hat jedoch eine spezielle Funktion und vertritt den [[Staat]] vor dem Obersten Gerichtshof in bestimmten Fällen bzw. spielt eine beratende Rolle bei der Prüfung von [[Rechtsmitteln]] wie Nichtigkeitsbeschwerden, Revisionsverfahren und Anträgen auf Wiederaufnahme"}, {"kategorie": "", "text": "Die Generalprokuratur ist eine wichtige Institution der Rechtskontrolle in Österreich, die den Obersten Gerichtshof (OGH) in Rechtsfragen unterstützt. Sie sorgt für die Einheitlichkeit der [[Rechtsprechung]] und schützt das Recht vor Fehlinterpretationen und Fehlern. Ihre unabhängige und neutrale Rolle macht sie zu einem wichtigen Instrument zur Sicherung der [[Rechtsstaatlichkeit]] in Österreich, indem sie in Verfahren vor dem OGH als Beraterin auftritt und in besonderen Fällen Wiederaufnahmeanträge stellt."}]'::jsonb, ''),
  ('schdoodsaunwoitschoft', 'Schdoodsaunwoitschoft', '', '', '', '', 'Staatsanwaltschaft', '[{"kategorie": "allg.", "text": "\"unabhängige Behörde, die für die Strafverfolgung zuständig ist\""}, {"kategorie": "", "text": "Sie hat die Aufgabe, Straftaten zu untersuchen, strafrechtliche Verfahren zu leiten und vor Gericht Anklage zu erheben. Dabei handelt die Staatsanwaltschaft im öffentlichen Interesse und sorgt dafür, dass Straftäter zur Verantwortung gezogen werden und der [[Rechtsstaat]] aufrechterhalten bleibt"}, {"kategorie": "", "text": "Im österreichischen Rechtssystem hat die Staatsanwaltschaft die Oberaufsicht über die Ermittlungen der Polizei. Das bedeutet, dass die Polizei unter der Anordnung und Leitung der Staatsanwaltschaft arbeitet. Sie kann Ermittlungen anordnen, bestimmte Beweismittel einfordern und die Polizei anweisen, weitere Schritte zur Klärung eines Sachverhalts zu unternehmen"}, {"kategorie": "", "text": "Die Staatsanwaltschaft entscheidet auch über die Einleitung von Zwangsmaßnahmen wie Hausdurchsuchungen, Festnahmen oder Überwachungen, wobei solche Maßnahmen in der Regel von einem Gericht genehmigt werden müssen"}, {"kategorie": "", "text": "Die Staatsanwaltschaft entscheidet nach Abschluss der Ermittlungen, ob genug Beweise vorliegen, um Anklage zu erheben, oder ob das Verfahren eingestellt wird.\nBei genügendem Verdacht erhebt sie Anklage vor dem zuständigen [[Gericht]]. Die Staatsanwaltschaft tritt dann im Strafverfahren als Vertreterin des Staates auf und fordert im Prozess die Bestrafung der Täter"}, {"kategorie": "", "text": "Die Staatsanwaltschaft in Österreich ist hierarchisch organisiert. Auf der unteren Ebene gibt es Bezirks- und Landesstaatsanwaltschaften, die für die Strafverfolgung in ihrem jeweiligen Zuständigkeitsbereich zuständig sind. Auf der höheren Ebene steht die Oberstaatsanwaltschaft, die Aufsicht über die unteren Instanzen führt. Darüber hinaus gibt es die [[Generalprokuratur]], die den [[Obersten]] Gerichtshof in Rechtsfragen berät, jedoch nicht direkt in Strafverfahren eingreift"}, {"kategorie": "", "text": "Die Staatsanwaltschaft in Österreich ist ein zentrales Organ der Strafrechtspflege. Sie arbeitet unabhängig, jedoch im öffentlichen Interesse, und gewährleistet, dass sowohl strafrechtlich relevante Handlungen verfolgt als auch die Rechte der Beschuldigten gewahrt werden. Die enge Zusammenarbeit mit [[Polizei]] und Gerichten sichert eine rechtsstaatliche und faire Strafverfolgung."}]'::jsonb, ''),
  ('wega', 'WEGA', '', '', '', '', 'WEGA', '[{"kategorie": "", "text": "Die WEGA ist eine der bekanntesten Polizeieinheiten Österreichs und wird bei gewalttätigen Einsätzen, Geiselnahmen, Festnahmen bewaffneter Personen und zur Unterstützung bei Großveranstaltungen oder Demonstrationen eingesetzt. Sie ist eine schnelle Eingreiftruppe, die in der Stadt Wien operiert"}, {"kategorie": "", "text": "Die WEGA gehört zur Polizeidirektion Wien und ist ausschließlich in der Hauptstadt Wien im Einsatz, wobei sie auf extrem schnelles Reagieren in Krisensituationen ausgelegt ist"}, {"kategorie": "", "text": "Die Einheit besteht aus mehreren Teams, die auf Spezialaufgaben wie Sturmangriffe, Verhandlungsführung und den Einsatz schwerer Ausrüstung trainiert sind"}, {"kategorie": "", "text": "Im Unterschied zur [[Cobra]], die eine nationale Einheit mit Spezialisierung auf Antiterroroperationen ist, liegt der Fokus der WEGA auf der raschen Reaktion bei lokalen Gefährdungssituationen in der Stadt Wien"}, {"kategorie": "", "text": "Während die Cobra bei besonders hochgefährlichen, geplanten Einsätzen zum Einsatz kommt, ist die WEGA eine Sofort-Einsatztruppe, die bei akuten Bedrohungen in städtischen Gebieten eingreift. Hierzu zählen: (i) Geiselnahmen und Amoklagen,  (ii) Festnahmen bewaffneter oder gewaltbereiter Täter, (iii) Sicherung von Großveranstaltungen, Demonstrationen und Fußballspielen,  (iv) Objektschutz und Personenschutz bei besonders gefährdeten Personen.\nDarüber hinaus ist die WEGA auch bei Razzien und Durchsuchungen involviert, wenn ein hohes Gefährdungspotenzial vorliegt."}]'::jsonb, ''),
  ('cobra', 'Cobra', '', '', '', '', 'Cobra', '[{"kategorie": "", "text": "Sie ist eine der bekanntesten und schlagkräftigsten Spezialeinheiten des Landes und kommt bei besonders gefährlichen oder komplexen Situationen zum Einsatz, wie etwa bei Geiselnahmen, Terroranschlägen oder der Festnahme von schwer bewaffneten Kriminellen. Die Einheit ist dem Bundesministerium für Inneres (BMI) unterstellt"}, {"kategorie": "", "text": "Das Einsatzkommando Cobra wurde 1978 gegründet (ursprünglich als \"Gendarmerieeinsatzkommando\"), nach dem Anschlag auf die OPEC-Konferenz in Wien 1975, um eine schlagkräftige Einheit für den Kampf gegen Terrorismus zu schaffen"}, {"kategorie": "", "text": "Die Hauptaufgabe der Cobra ist der Antiterrorkampf. Sie wird bei Geiselnahmen, Entführungen, terroristischen Bedrohungen und Amoklagen eingesetzt"}, {"kategorie": "", "text": "Darüber hinaus führt die Cobra auch Personenschutz für besonders gefährdete Persönlichkeiten durch, unterstützt bei der Festnahme von Schwerkriminellen und ist bei Luftsicherheitsoperationen wie der Sicherung von Flugzeugen beteiligt"}, {"kategorie": "", "text": "Sie ist auch für Geiselbefreiungen und die Bekämpfung von organisierter Kriminalität sowie Gefahrenabwehr in Extremsituationen verantwortlich"}, {"kategorie": "", "text": "Die Cobra ist Teil der Bundespolizei und untersteht dem Direktor der Spezialeinheiten, der dem Innenministerium angehört. Die Einheit ist zentral organisiert, aber auch in mehreren Standorten in Österreich verteilt, um rasch an verschiedenen Einsatzorten verfügbar zu sein"}, {"kategorie": "", "text": "Sie hat verschiedene spezialisierte Teams, die auf unterschiedliche Aufgaben spezialisiert sind, wie etwa Sprengstoffentschärfung, Scharfschützen, Taucher oder Abseilspezialisten"}, {"kategorie": "", "text": "Die Cobra verwendet hochmoderne Ausrüstung und Waffensysteme, die speziell für Antiterror- und Spezialoperationen entwickelt wurden. Dazu gehören Scharfschützengewehre, Sturmgewehre, Schutzwesten sowie modernste Kommunikationstechnologie"}, {"kategorie": "", "text": "Die Cobra arbeitet eng mit anderen internationalen Spezialeinheiten zusammen und nimmt an gemeinsamen Übungen und Einsätzen teil. Sie ist Mitglied der ATLAS-Gruppe, einem Zusammenschluss europäischer Spezialeinheiten, die bei grenzüberschreitenden Bedrohungen, wie Terrorismus oder schwerer organisierter Kriminalität, kooperieren."}]'::jsonb, ''),
  ('polizei', 'Polizei', '', '', '', '', 'Polizei', '[{"kategorie": "pol.", "text": "\"staatliche Institution, die für die Aufrechterhaltung der öffentlichen Sicherheit, den Schutz der Bürger und die Durchsetzung von [[Gesetzen]] in Österreich zuständig ist\""}, {"kategorie": "", "text": "Sie gehört zur [[Exekutive]] und untersteht dem Bundesministerium für Inneres (BMI). Die österreichische Polizei ist in verschiedene Einheiten und Abteilungen gegliedert und spielt eine zentrale Rolle bei der Kriminalitätsbekämpfung, Gefahrenabwehr und Sicherheitsgewährleistung"}, {"kategorie": "", "text": "Seit 2005 gibt es eine einheitliche Bundespolizei, die aus der Zusammenlegung von Bundessicherheitswache, Gendarmerie und Kriminalpolizei hervorgegangen ist"}, {"kategorie": "", "text": "Sie gliedert sich in verschiedene Landespolizeidirektionen, die für die einzelnen [[Bundesländer]] zuständig sind. Innerhalb der Länder sind diese Direktionen in Polizeiinspektionen aufgeteilt, die die lokale Ebene der Polizeiarbeit repräsentieren"}, {"kategorie": "", "text": "Die Kriminalpolizei ist eine spezialisierte Einheit der österreichischen Polizei, die sich auf die Untersuchung von Straftaten konzentriert. Sie befasst sich mit der Aufklärung schwerer Verbrechen wie Mord, Diebstahl, Betrug, Drogenhandel und organisierter Kriminalität"}, {"kategorie": "", "text": "Die österreichische Polizei verfügt auch über mehrere Spezialeinheiten, die für besondere Einsätze ausgebildet sind: (i) Cobra (eine Spezialeinheit für Antiterror-Einsätze und Geiselbefreiungen),  (ii) EKO Cobra und WEGA (beide Einheiten sind für den Schutz besonders gefährdeter Personen und die Bewältigung von Extremsituationen, wie etwa terroristischen Bedrohungen oder schwer bewaffneten Kriminellen, zuständig)"}, {"kategorie": "", "text": "Die österreichische Polizei arbeitet eng mit anderen staatlichen Behörden, wie der [[Staatsanwaltschaft]], den [[Gerichten]], dem [[Bundesheer]] und den [[Zollbehörden]], zusammen, ebenso auch mit internationalen Polizeibehörden wie Europol oder Interpol"}, {"kategorie": "", "text": "Die österreichische Polizei handelt auf Grundlage von Gesetzen wie dem Sicherheitspolizeigesetz (SPG), der Strafprozessordnung (StPO) und dem Polizeilichen Staatsschutzgesetz (PStSG). Diese Gesetze regeln die Aufgaben, Befugnisse und Grenzen polizeilichen Handelns"}, {"kategorie": "", "text": "Sie handelt im Rahmen eines strikten rechtlichen Rahmens, der sicherstellt, dass ihre Maßnahmen im Einklang mit der [[Verfassung]] und den [[Menschenrechten]] stehen. Mit ihrer breiten Palette an Aufgaben und spezialisierten Einheiten trägt die Polizei maßgeblich zur [[Rechtsstaatlichkeit]] und zum Schutz der Bevölkerung in Österreich bei."}]'::jsonb, ''),
  ('vasaummlungsfreiheit', 'Vasaummlungsfreiheit', '', '', '', '', 'Versammlungsfreiheit', '[{"kategorie": "pol.", "text": "\"Recht der [[Bürger]], sich friedlich zu versammeln, um ihre Meinungen zu äußern, politische oder gesellschaftliche Anliegen zu vertreten und öffentliche Kundgebungen abzuhalten\""}, {"kategorie": "", "text": "In Österreich ist dieses Grundrecht verfassungsrechtlich geschützt und spielt eine zentrale Rolle in der [[Demokratie]] und dem [[politischen]] Diskurs"}, {"kategorie": "", "text": "Die Versammlungsfreiheit ist in Artikel 12 des Staatsgrundgesetzes von 1867 und in der Europäischen Menschenrechtskonvention (EMRK) verankert, die in Österreich Verfassungsrang hat. Das Recht gewährleistet, dass sich Bürger ohne vorherige Genehmigung friedlich und ohne Waffen versammeln dürfen"}, {"kategorie": "", "text": "Nach österreichischem Recht müssen öffentliche Versammlungen mindestens 24 Stunden im Voraus bei den zuständigen Behörden (meist bei der [[Polizei]]) angemeldet werden. Eine Genehmigung ist nicht erforderlich, jedoch darf die Versammlung untersagt oder aufgelöst werden, wenn sie die öffentliche Sicherheit gefährdet oder gegen Gesetze verstößt"}, {"kategorie": "", "text": "Die Versammlungsfreiheit spielt eine zentrale Rolle in der [[politischen]] Willensbildung. Sie ermöglicht es Bürgern, ihre Meinungen öffentlich zu äußern, politische Entscheidungen zu beeinflussen und gegen Maßnahmen der [[Regierung]] zu protestieren. Sie ist ein unverzichtbares Instrument zur politischen Meinungsbildung und zur Teilnahme am öffentlichen Leben in einer demokratischen Gesellschaft."}]'::jsonb, ''),
  ('schdoodsoagane', 'Schdoodsoagane', '', '', '', '', 'Staatsorgane', '[{"kategorie": "pol.", "text": "\"zentrale Institutionen, welche die verschiedenen Aufgaben des [[Staates]] in den Bereichen [[Gesetzgebung]], [[Verwaltung]] und [[Rechtsprechung]] übernehmen\""}, {"kategorie": "", "text": "Sie sind die Träger der [[Staatsgewalt]] und sorgen für die Umsetzung der [[politischen]] Ordnung und den reibungslosen Ablauf des staatlichen Geschehens"}, {"kategorie": "", "text": "Diese Staatsorgane unterliegen den Prinzipien der [[Gewaltenteilung]] und arbeiten auf Bundes-, Landes- und Gemeindeebene"}, {"kategorie": "", "text": "Die Staatsorgane in Österreich unterliegen der Rechenschaftspflicht gegenüber der Bevölkerung und den Institutionen des Staates. Die [[Legislative]] überwacht die [[Exekutive]], während die [[Judikative]] die Einhaltung der [[Gesetze]] sicherstellt und unabhängig Entscheidungen trifft"}, {"kategorie": "", "text": "Diese Organe, von den gesetzgebenden [[Parlamenten]] bis hin zu den [[Gerichten]], bilden das Rückgrat des österreichischen Staates. Ihre klare Abgrenzung und Zusammenarbeit basieren auf dem Prinzip der Gewaltenteilung, um Machtmissbrauch zu verhindern und das Funktionieren der [[Demokratie]] zu gewährleisten."}]'::jsonb, ''),
  ('schdood', 'Schdood', '', '', '', '', 'Staat', '[{"kategorie": "", "text": "Der österreichische Staat ist eine demokratische Republik und ein Bundesstaat in Mitteleuropa, der auf den Prinzipien der [[Demokratie]], der [[Rechtsstaatlichkeit]] und der [[Gewaltenteilung]] beruht. Der Staat umfasst die politischen und rechtlichen Institutionen sowie die geografischen und gesellschaftlichen Strukturen, die das Gemeinwesen Österreichs bilden"}, {"kategorie": "", "text": "Österreich ist seit der Verfassung von 1920 eine demokratische Republik. Das bedeutet, dass alle [[Staatsgewalt]] vom Volk ausgeht und das Volk durch gewählte Vertreter in der Politik mitbestimmt. Die Österreichische [[Bundesverfassung]] bildet die Grundlage des Staates und regelt die politische und rechtliche Ordnung. Sie legt die [[Grundrechte]] der Bürger fest und beschreibt die Funktionsweise der [[Staatsorgane]]"}, {"kategorie": "", "text": "Österreich ist ein föderaler Staat, was bedeutet, dass es sich aus dem [[Bund]] und den neun [[Bundesländern]] zusammensetzt"}, {"kategorie": "", "text": "Der österreichische Staat basiert auf dem Prinzip der [[Gewaltenteilung]] zwischen [[Legislative]], [[Exekutive]] und [[Judikative]]"}, {"kategorie": "", "text": "Das Staatsoberhaupt des österreichischen Staates ist der [[Bundespräsident]], der alle sechs Jahre direkt vom Volk gewählt wird. Der Bundespräsident hat in erster Linie repräsentative Aufgaben, besitzt aber auch wichtige verfassungsrechtliche Befugnisse, wie die Ernennung des [[Bundeskanzlers]] und der [[Minister]] sowie das Recht, den [[Nationalrat]] aufzulösen"}, {"kategorie": "", "text": "Der österreichische Staat ist ein [[Rechtsstaat]], was bedeutet, dass alle staatlichen Handlungen auf der Grundlage von [[Gesetzen]] erfolgen müssen. Die Einhaltung der Gesetze wird durch unabhängige [[Gerichte]] überwacht, und die Bürger haben das Recht auf rechtlichen Schutz. Die [[Verfassung]] garantiert den Schutz der [[Grund-]] und Menschenrechte sowie die Freiheit des Einzelnen vor staatlicher Willkür"}, {"kategorie": "", "text": "Der österreichische Staat ist ein aktives Mitglied der internationalen Gemeinschaft und gehört Organisationen wie den Vereinten Nationen (UNO), der Europäischen Union (EU) und der Organisation für Sicherheit und Zusammenarbeit in Europa (OSZE) an"}, {"kategorie": "", "text": "Österreich vertritt eine neutrale Außenpolitik, was bedeutet, dass es sich verpflichtet hat, nicht an militärischen Bündnissen teilzunehmen. Die [[immerwährende]] Neutralität ist ein wesentlicher Bestandteil der Außenpolitik und wurde 1955 in der Verfassung verankert."}]'::jsonb, '')
